struct Pattern23OffsetRule {
    int offset;           // 相对于 01 0A 00 23 特征的偏移（负数为往前，正数为往后）
    int length;           // 要替换的字节数
    bool enabled;         // 是否启用该规则
    std::string name;     // 规则名称（便于识别）

    Pattern23OffsetRule() : offset(0), length(1), enabled(false), name("") {}
    Pattern23OffsetRule(int off, int len, bool en, const std::string& n)
        : offset(off), length(len), enabled(en), name(n) {}
};

