// ========== 伪心跳：替换数量规则（新版，支持策略）==========
// 说明：旧版 g_heartbeatReplaceLimit / g_enableLimitCleanup 保留仅用于迁移与兼容显示，不再驱动核心替换逻辑。
enum class HeartbeatReplacePostLimitStrategy {
    SendOriginal = 0,             // 达到后：后续只发原包（不再从池中取伪包）
    CycleFakeThenOriginal = 1     // 达到后：按比例循环（先发N条伪包，再发M条原包）
};

enum class HeartbeatReplaceOutcome : uint8_t {
    Unknown = 0,
    Replaced = 1,          // 本次确实进行了伪包替换（消费了数据池）
    SkippedByRule = 2,     // 规则到达后策略：本次发送原包段
    NotReplaced = 3        // 未替换（不满足条件/无池数据/失败等）
};

struct HeartbeatReplaceCountRule {
    int id = 0;
    bool enabled = true;
    std::string name;

    // 触发阈值：成功替换(发伪包)达到 N 次后进入"到达后策略"
    int replaceLimit = 1;

    HeartbeatReplacePostLimitStrategy postLimitStrategy = HeartbeatReplacePostLimitStrategy::SendOriginal;

    // 到达阈值时是否清理数据池中该账号/ID的数据（只执行一次）
    bool clearPoolOnReach = false;

    // 到达后"原包段"是否仍执行 WPE 滤镜（Always 不执行 03 滤镜）
    bool applyWpeOnOriginalSegment = true;

    // 断开连接后是否重置计数（让下一次连接从0开始计数）
    bool resetCountOnDisconnect = true;

    // 仅当 postLimitStrategy == CycleFakeThenOriginal 生效
    int postLimitFakeN = 1;
    int postLimitOriginalN = 1;
};

struct HeartbeatReplaceRuntimeState {
    int ruleId = 0;
    uint64_t rulesVersion = 0;

    int replacementsDone = 0;      // 已成功替换(发伪包)次数
    bool reached = false;          // 是否已到达阈值
    bool reachCleanupDone = false; // 到达时清理是否已执行

    // post-limit cycle 状态（仅 CycleFakeThenOriginal 使用）
    bool cycleSendFake = true;
    int cycleRemaining = 0;
};

static std::vector<HeartbeatReplaceCountRule> g_hbReplaceCountRules;
static int g_hbReplaceCountRulesNextId = 1;
static int g_hbReplaceCountRulesSelectedId = -1;
static bool g_showHbReplaceCountRuleModal = false;
static bool g_hbReplaceCountRuleIsNew = true;
static HeartbeatReplaceCountRule g_hbReplaceCountRuleEditData;
static char g_hbReplaceCountRuleNameBuffer[128] = "";
static std::atomic<bool> g_hbReplaceCountRulesDirty = false;
static std::atomic<uint64_t> g_hbReplaceCountRulesVersion = 1;

static std::map<std::string, HeartbeatReplaceRuntimeState> g_hbReplaceRuntimeStates; // key=账号/ID
static std::mutex g_hbReplaceRuntimeMutex;

static std::string GetHbReplacePostLimitStrategyName(HeartbeatReplacePostLimitStrategy s) {
    switch (s) {
        case HeartbeatReplacePostLimitStrategy::SendOriginal: return "到达后只发原包";
        case HeartbeatReplacePostLimitStrategy::CycleFakeThenOriginal: return "到达后按比例循环";
        default: return "未知";
    }
}

static std::string HbReplaceRules_MakeKey(bool isSameAlgorithm, const std::string& gameID, const std::string& socksUsername) {
    return isSameAlgorithm ? ("G:" + gameID) : ("U:" + socksUsername);
}

static void HbReplaceRules_BumpVersionAndResetRuntime() {
    g_hbReplaceCountRulesVersion.fetch_add(1);
    std::lock_guard<std::mutex> lock(g_hbReplaceRuntimeMutex);
    g_hbReplaceRuntimeStates.clear();
}

static HeartbeatReplaceCountRule* HbReplaceRules_GetFirstEnabledRule() {
    for (auto& rule : g_hbReplaceCountRules) {
        if (rule.enabled && rule.replaceLimit > 0) return &rule;
    }
    return nullptr;
}

static std::string HbReplaceRules_ExportToJson() {
    Json::Value root;
    root["version"] = 1;
    Json::Value rules(Json::arrayValue);

    for (const auto& rule : g_hbReplaceCountRules) {
        Json::Value r;
        r["id"] = rule.id;
        r["enabled"] = rule.enabled;
        r["name"] = rule.name;
        r["replaceLimit"] = rule.replaceLimit;
        r["postLimitStrategy"] = static_cast<int>(rule.postLimitStrategy);
        r["clearPoolOnReach"] = rule.clearPoolOnReach;
        r["applyWpeOnOriginalSegment"] = rule.applyWpeOnOriginalSegment;
        r["resetCountOnDisconnect"] = rule.resetCountOnDisconnect;
        r["postLimitFakeN"] = rule.postLimitFakeN;
        r["postLimitOriginalN"] = rule.postLimitOriginalN;
        rules.append(r);
    }
    root["rules"] = rules;

    Json::StreamWriterBuilder builder;
    builder["indentation"] = "";
    return Json::writeString(builder, root);
}

static bool HbReplaceRules_ImportFromJson(const std::string& jsonStr) {
    if (jsonStr.empty()) return false;

    Json::CharReaderBuilder builder;
    Json::Value root;
    std::string errs;
    std::istringstream iss(jsonStr);
    if (!Json::parseFromStream(builder, iss, &root, &errs)) {
        AB_LOG_ERROR("[伪心跳] 加载替换数量规则失败: JSON解析失败: " + errs);
        return false;
    }

    if (!root.isObject()) return false;
    const auto rulesNode = root["rules"];
    if (!rulesNode.isArray()) return false;

    std::vector<HeartbeatReplaceCountRule> loaded;
    int maxId = 0;

    for (const auto& r : rulesNode) {
        HeartbeatReplaceCountRule rule;
        rule.id = r.get("id", 0).asInt();
        rule.enabled = r.get("enabled", true).asBool();
        rule.name = r.get("name", "").asString();
        rule.replaceLimit = std::max(1, r.get("replaceLimit", 1).asInt());
        rule.postLimitStrategy = static_cast<HeartbeatReplacePostLimitStrategy>(r.get("postLimitStrategy", 0).asInt());
        rule.clearPoolOnReach = r.get("clearPoolOnReach", false).asBool();
        rule.applyWpeOnOriginalSegment = r.get("applyWpeOnOriginalSegment", true).asBool();
        rule.resetCountOnDisconnect = r.get("resetCountOnDisconnect", true).asBool();
        rule.postLimitFakeN = std::max(0, r.get("postLimitFakeN", 1).asInt());
        rule.postLimitOriginalN = std::max(0, r.get("postLimitOriginalN", 1).asInt());

        if (rule.id <= 0) continue;
        if (rule.name.empty()) rule.name = "规则#" + std::to_string(rule.id);

        maxId = std::max(maxId, rule.id);
        loaded.push_back(rule);
    }

    g_hbReplaceCountRules = std::move(loaded);
    g_hbReplaceCountRulesNextId = std::max(1, maxId + 1);
    HbReplaceRules_BumpVersionAndResetRuntime();
    return true;
}

static void SaveHeartbeatReplaceRulesConfig() {
    if (!g_database) return;
    if (!g_hbReplaceCountRulesDirty.exchange(false)) return;

    const std::string json = HbReplaceRules_ExportToJson();
    g_database->SetConfigValue("heartbeat_replace_rules_json", json);
    AB_LOG_INFO("[伪心跳] 已保存替换数量规则到 config.db，共 " + std::to_string(g_hbReplaceCountRules.size()) + " 条");
}

static void LoadHeartbeatReplaceRulesConfig() {
    if (!g_database) return;

    const std::string json = g_database->GetConfigValue("heartbeat_replace_rules_json", "");
    if (!json.empty()) {
        if (HbReplaceRules_ImportFromJson(json)) {
            AB_LOG_INFO("[伪心跳] 已从 config.db 加载替换数量规则，共 " + std::to_string(g_hbReplaceCountRules.size()) + " 条");
            g_hbReplaceCountRulesDirty = false;
            return;
        }
    }

    // 迁移：旧版全局配置 -> 规则#1
    if (g_heartbeatReplaceLimit > 0) {
        HeartbeatReplaceCountRule rule;
        rule.id = g_hbReplaceCountRulesNextId++;
        rule.enabled = true;
        rule.name = "默认规则";
        rule.replaceLimit = std::max(1, g_heartbeatReplaceLimit);
        rule.postLimitStrategy = HeartbeatReplacePostLimitStrategy::SendOriginal;
        rule.clearPoolOnReach = g_enableLimitCleanup;
        rule.applyWpeOnOriginalSegment = true;
        rule.resetCountOnDisconnect = true;
        rule.postLimitFakeN = 1;
        rule.postLimitOriginalN = 1;

        g_hbReplaceCountRules.clear();
        g_hbReplaceCountRules.push_back(rule);
        HbReplaceRules_BumpVersionAndResetRuntime();

        g_hbReplaceCountRulesDirty = true;
        SaveHeartbeatReplaceRulesConfig();
        AB_LOG_INFO("[伪心跳] 已将旧版替换数量限制迁移为规则系统");
    }
}

static void HbReplaceRules_ClearPoolForKey(
    CollectedPacketPool* sourcePool,
    bool isSameAlgorithm,
    const std::string& gameID,
    const std::string& socksUsername)
{
    if (!sourcePool) return;

    if (isSameAlgorithm) {
        if (!gameID.empty() && sourcePool->GetCountByGameID(gameID) > 0) {
            sourcePool->ClearByGameID(gameID);
            AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|" + gameID + "] 已清理内存池中的数据");
        }
    } else {
        if (!socksUsername.empty() && sourcePool->GetCountByUsername(socksUsername) > 0) {
            sourcePool->ClearByUsername(socksUsername);
            AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|" + socksUsername + "] 已清理内存池中的数据");
        }
    }
}

static HeartbeatReplaceRuntimeState& HbReplaceRules_GetStateLocked(
    const std::string& key,
    const HeartbeatReplaceCountRule& rule)
{
    auto& state = g_hbReplaceRuntimeStates[key];
    const uint64_t currentVersion = g_hbReplaceCountRulesVersion.load();
    if (state.ruleId != rule.id || state.rulesVersion != currentVersion) {
        state = HeartbeatReplaceRuntimeState{};
        state.ruleId = rule.id;
        state.rulesVersion = currentVersion;
        state.cycleSendFake = true;
        state.cycleRemaining = 0;
    }
    return state;
}

static bool HbReplaceRules_ShouldAttemptReplace(
    const std::string& key,
    CollectedPacketPool* sourcePool,
    bool isSameAlgorithm,
    const std::string& gameID,
    const std::string& socksUsername)
{
    HeartbeatReplaceCountRule* rule = HbReplaceRules_GetFirstEnabledRule();
    if (!rule) return true; // 未配置规则：不限制，继续替换

    std::lock_guard<std::mutex> lock(g_hbReplaceRuntimeMutex);
    auto& state = HbReplaceRules_GetStateLocked(key, *rule);

    if (!state.reached && state.replacementsDone >= rule->replaceLimit) {
        state.reached = true;
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE,
            "[伪心跳|" + key + "] 已达到替换数量阈值 (" + std::to_string(rule->replaceLimit) + "条)，进入到达后策略: " +
            GetHbReplacePostLimitStrategyName(rule->postLimitStrategy));
    }

    if (state.reached && rule->clearPoolOnReach && !state.reachCleanupDone) {
        state.reachCleanupDone = true;
        HbReplaceRules_ClearPoolForKey(sourcePool, isSameAlgorithm, gameID, socksUsername);
    }

    if (!state.reached) return true;

    if (rule->postLimitStrategy == HeartbeatReplacePostLimitStrategy::SendOriginal) {
        return false;
    }

    if (rule->postLimitStrategy == HeartbeatReplacePostLimitStrategy::CycleFakeThenOriginal) {
        if (state.cycleRemaining <= 0) {
            // 初始化/切换段
            if (state.cycleSendFake) {
                state.cycleRemaining = std::max(0, rule->postLimitFakeN);
                if (state.cycleRemaining <= 0) {
                    state.cycleSendFake = false;
                    state.cycleRemaining = std::max(0, rule->postLimitOriginalN);
                }
            } else {
                state.cycleRemaining = std::max(0, rule->postLimitOriginalN);
                if (state.cycleRemaining <= 0) {
                    state.cycleSendFake = true;
                    state.cycleRemaining = std::max(0, rule->postLimitFakeN);
                }
            }
        }

        // 如果两边都是0，就永远发原包
        if (state.cycleRemaining <= 0) return false;
        return state.cycleSendFake;
    }

    return false;
}

static void HbReplaceRules_OnOriginalSentAfterReach(const std::string& key) {
    HeartbeatReplaceCountRule* rule = HbReplaceRules_GetFirstEnabledRule();
    if (!rule) return;

    if (rule->postLimitStrategy != HeartbeatReplacePostLimitStrategy::CycleFakeThenOriginal) return;

    std::lock_guard<std::mutex> lock(g_hbReplaceRuntimeMutex);
    auto it = g_hbReplaceRuntimeStates.find(key);
    if (it == g_hbReplaceRuntimeStates.end()) return;
    auto& state = it->second;
    if (!state.reached) return;
    if (state.cycleSendFake) return; // 当前应发伪包，不在这里推进

    if (state.cycleRemaining > 0) state.cycleRemaining--;
    if (state.cycleRemaining <= 0) {
        state.cycleSendFake = true;
        state.cycleRemaining = 0; // 下一次 ShouldAttemptReplace 会重新填充
    }
}

static void HbReplaceRules_OnFakeSentSuccessfully(
    const std::string& key,
    CollectedPacketPool* sourcePool,
    bool isSameAlgorithm,
    const std::string& gameID,
    const std::string& socksUsername)
{
    HeartbeatReplaceCountRule* rule = HbReplaceRules_GetFirstEnabledRule();
    if (!rule) return;

    std::lock_guard<std::mutex> lock(g_hbReplaceRuntimeMutex);
    auto& state = HbReplaceRules_GetStateLocked(key, *rule);

    state.replacementsDone++;

    if (!state.reached && state.replacementsDone >= rule->replaceLimit) {
        state.reached = true;
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE,
            "[伪心跳|" + key + "] 已达到替换数量阈值 (" + std::to_string(rule->replaceLimit) + "条)，进入到达后策略: " +
            GetHbReplacePostLimitStrategyName(rule->postLimitStrategy));
    }

    if (state.reached && rule->clearPoolOnReach && !state.reachCleanupDone) {
        state.reachCleanupDone = true;
        HbReplaceRules_ClearPoolForKey(sourcePool, isSameAlgorithm, gameID, socksUsername);
    }

    if (state.reached && rule->postLimitStrategy == HeartbeatReplacePostLimitStrategy::CycleFakeThenOriginal) {
        // 仅当本次确实发出伪包时推进 cycle(fake段)
        if (!state.cycleSendFake) return;
        if (state.cycleRemaining > 0) state.cycleRemaining--;
        if (state.cycleRemaining <= 0) {
            state.cycleSendFake = false;
            state.cycleRemaining = 0; // 下一次 ShouldAttemptReplace 会重新填充
        }
    }

    if (rule->replaceLimit > 0) {
        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE,
            "[伪心跳|" + key + "] 替换计数: " + std::to_string(state.replacementsDone) + "/" + std::to_string(rule->replaceLimit));
    }
}

static HeartbeatReplaceCountRule* HbReplaceRules_FindRuleById(int id) {
    for (auto& r : g_hbReplaceCountRules) {
        if (r.id == id) return &r;
    }
    return nullptr;
}

static void HbReplaceRules_ResetEditData() {
    g_hbReplaceCountRuleEditData = HeartbeatReplaceCountRule{};
    g_hbReplaceCountRuleEditData.enabled = true;
    g_hbReplaceCountRuleEditData.replaceLimit = 1;
    g_hbReplaceCountRuleEditData.postLimitStrategy = HeartbeatReplacePostLimitStrategy::SendOriginal;
    g_hbReplaceCountRuleEditData.clearPoolOnReach = false;
    g_hbReplaceCountRuleEditData.applyWpeOnOriginalSegment = true;
    g_hbReplaceCountRuleEditData.resetCountOnDisconnect = true;
    g_hbReplaceCountRuleEditData.postLimitFakeN = 1;
    g_hbReplaceCountRuleEditData.postLimitOriginalN = 1;
    strcpy_s(g_hbReplaceCountRuleNameBuffer, "");
}

static void HbReplaceRules_ResetRuntimeForKey(const std::string& key) {
    if (key.empty()) return;
    std::lock_guard<std::mutex> lock(g_hbReplaceRuntimeMutex);
    g_hbReplaceRuntimeStates.erase(key);
}

static void HbReplaceRules_OpenAddModal();
static void HbReplaceRules_OpenEditModal(int id);
static void RenderHeartbeatReplaceCountRuleModal(bool& needsRedraw);

static bool HbReplaceRules_RemoveById(int id) {
    for (size_t i = 0; i < g_hbReplaceCountRules.size(); i++) {
        if (g_hbReplaceCountRules[i].id == id) {
            g_hbReplaceCountRules.erase(g_hbReplaceCountRules.begin() + i);
            if (g_hbReplaceCountRulesSelectedId == id) g_hbReplaceCountRulesSelectedId = -1;
            HbReplaceRules_BumpVersionAndResetRuntime();
            g_hbReplaceCountRulesDirty = true;
            return true;
        }
    }
    return false;
}

static void HbReplaceRules_MoveUp(int id) {
    for (size_t i = 1; i < g_hbReplaceCountRules.size(); i++) {
        if (g_hbReplaceCountRules[i].id == id) {
            std::swap(g_hbReplaceCountRules[i - 1], g_hbReplaceCountRules[i]);
            HbReplaceRules_BumpVersionAndResetRuntime();
            g_hbReplaceCountRulesDirty = true;
            return;
        }
    }
}

static void HbReplaceRules_MoveDown(int id) {
    for (size_t i = 0; i + 1 < g_hbReplaceCountRules.size(); i++) {
        if (g_hbReplaceCountRules[i].id == id) {
            std::swap(g_hbReplaceCountRules[i], g_hbReplaceCountRules[i + 1]);
            HbReplaceRules_BumpVersionAndResetRuntime();
            g_hbReplaceCountRulesDirty = true;
            return;
        }
    }
}



// ===== 文件导入相关 =====
static int g_importedFileCount = 0;  // 导入的文件数量




// ===== CRC32 计算函数（IEEE 802.3 多项式 0xEDB88320）=====
// 计算给定数据的 CRC32 校验值，返回 4 字节结果
static void CalculateCRC32(const std::vector<uint8_t>& data, int startPos, int endPos,
    uint8_t& crc0, uint8_t& crc1, uint8_t& crc2, uint8_t& crc3) {
    uint8_t c0 = 255, c1 = 255, c2 = 255, c3 = 255;

    for (int idx = startPos; idx <= endPos && idx < static_cast<int>(data.size()); idx++) {
        uint8_t byte = data[idx];
        c0 ^= byte;

        for (int i = 0; i < 8; i++) {
            uint8_t carry = c0 & 1;
            uint8_t b1 = c1 & 1;
            uint8_t b2 = c2 & 1;
            uint8_t b3 = c3 & 1;

            c0 >>= 1;
            c1 >>= 1;
            c2 >>= 1;
            c3 >>= 1;

            if (b1) c0 |= 128;
            if (b2) c1 |= 128;
            if (b3) c2 |= 128;

            if (carry) {
                c0 ^= 0x20;  // 0xEDB88320 的字节0
                c1 ^= 0x83;  // 0xEDB88320 的字节1
                c2 ^= 0xB8;  // 0xEDB88320 的字节2
                c3 ^= 0xED;  // 0xEDB88320 的字节3
            }
        }
    }

    // 最终取反
    crc0 = c0 ^ 255;
    crc1 = c1 ^ 255;
    crc2 = c2 ^ 255;
    crc3 = c3 ^ 255;
}

// 初始化函数（在main函数开始时调用）
void InitializePacketTypeFilters() {
    // 采集逻辑：默认全部启用
    for (int type : g_collectorPacketTypes) {
        g_collectorPacketTypeEnabled[type] = true;
        g_collectorDisplayFilter[type] = true;
    }

    // 伪心跳：默认全部启用
    for (int type : g_heartbeatPacketTypes) {
        g_heartbeatPacketTypeEnabled[type] = true;
    }

    
}


