// ===== ?? 新增：判断是否应该加载心跳数据的辅助函数 =====
bool ShouldLoadHeartbeat(const HeartbeatRecord& record) {
    // 必须有pattern数据
    if (record.pattern23Data.empty() && record.pattern09Data.empty()) {
        return false;
    }

    // 必须有有效的gameID
    if (record.gameID.empty() || record.gameID.length() < 2) {
        return false;
    }

    // 根据开关决定是否过滤00开头的ID
    bool is00ID = (record.gameID[0] == '0' && record.gameID[1] == '0');
    if (is00ID && !g_allowHeartbeat00ID) {
        return false;
    }

    // 根据开关决定是否过滤_OB结尾的ID
    if (record.gameID.length() >= 3) {
        bool isOBID = (record.gameID.substr(record.gameID.length() - 3) == "_OB");
        if (isOBID && !g_allowHeartbeatOBID) {
            return false;
        }
    }

    return true;
}

// ===== ?? 新增：根据加载模式构建DB文件路径 =====
std::string GetHeartbeatDbPath(StorageMode mode) {
    auto now = std::chrono::system_clock::now();
    auto duration = now.time_since_epoch();
    auto seconds = std::chrono::duration_cast<std::chrono::seconds>(duration).count();
    seconds += 8 * 3600; // 北京时间 UTC+8

    time_t beijing_time = seconds;
    struct tm timeinfo;
    gmtime_s(&timeinfo, &beijing_time);

    std::stringstream ss;
    ss << "db/heartbeat_";

    if (mode == StorageMode::HOURLY) {
        ss << std::put_time(&timeinfo, "%Y-%m-%d-%H");  // 按小时格式
    } else {  // DAILY
        ss << std::put_time(&timeinfo, "%Y-%m-%d");     // 按天格式
    }

    ss << ".db";
    return ss.str();
}

