// ===== 检查数据包是否符合伪心跳条件 =====
bool IsHeartbeatPacket(const PacketInfo& packet) {
    // 条件1：必须有 gameID
    if (packet.gameID.empty()) {
        return false;
    }

    // 条件2：gameID 不能以 "00" 开头
    if (packet.gameID.length() >= 2 &&
        (packet.gameID[0] == '0' && packet.gameID[1] == '0')) {
        return false;
    }

    // 条件3：23特征是必要特征，09和62是可选特征（至少有一个）
    bool has23 = !packet.pattern_01_0a_00_23.empty();
    bool has09 = !packet.pattern_01_0a_00_09.empty();
    bool has62 = g_enableHeartbeat62Pattern && !packet.pattern_01_0a_00_62.empty();

    if (!has23 || (!has09 && !has62)) {
        return false;
    }

    return true;
}



// ========== 三角洲VTD专属滤镜 ==========
std::vector<uint8_t> ApplyVTDFilter(const std::vector<uint8_t>& data, const std::string& gameID) {
    // 检查数据包是否包含特征：00 03 00 00 0A 92 00 00 00 24
    std::vector<uint8_t> pattern = { 0x00, 0x03, 0x00, 0x00, 0x0A, 0x92, 0x00, 0x00, 0x00, 0x24 };

    int pos = PacketParser::FindPattern(data, pattern);

    if (pos == -1) {
        // 未找到特征，返回原始数据
        return data;
    }

    // 找到特征，创建修改后的数据
    std::vector<uint8_t> modifiedData = data;

    // 将第2个字节（索引1）的 03 改成 00
    // pos 是第一个字节的位置，所以 pos+1 是第二个字节
    if (pos + 1 < modifiedData.size()) {
        uint8_t originalByte = modifiedData[pos + 1];
        modifiedData[pos + 1] = 0x00;

        AB_LOG_INFO("[VTD滤镜|" + gameID + "] 检测到特征，位置:" +
            std::to_string(pos) + " | 修改前:[" +
            std::to_string((int)originalByte) + "] -> 修改后:[00]");
    }

    return modifiedData;
}


// ========== 03包头专属滤镜 ==========
std::vector<uint8_t> Apply03Filter(const std::vector<uint8_t>& data, const std::string& gameID) {
    // 检查是否为03包头（第4个字节，索引3）
    if (data.size() < 4 || data[3] != 0x03) {
        return data;
    }

    // 查找 01 0A 00 23 特征
    std::vector<uint8_t> pattern = { 0x01, 0x0A, 0x00, 0x23 };
    int pos = PacketParser::FindPattern(data, pattern);

    if (pos == -1) {
        return data;
    }

    // 创建修改后的数据
    std::vector<uint8_t> modifiedData = data;

    // 往后偏移3位
    int targetPos = pos + 7;

    if (targetPos < modifiedData.size()) {
        uint8_t originalByte = modifiedData[targetPos];
        uint8_t randomValue = static_cast<uint8_t>(rand() % 256);
        modifiedData[targetPos] = randomValue;

        AB_LOG_INFO("[03滤镜|" + gameID + "] 位置:" +
            std::to_string(targetPos) + " | [" +
            std::to_string((int)originalByte) + "] -> [" +
            std::to_string((int)randomValue) + "]");
    }

    return modifiedData;
}




// ========== Base64编码 ==========
std::string Base64Encode(const std::vector<uint8_t>& data) {
    if (data.empty()) return "";

    DWORD base64Len = 0;
    if (!CryptBinaryToStringA(data.data(), data.size(),
        CRYPT_STRING_BASE64 | CRYPT_STRING_NOCRLF, NULL, &base64Len)) {
        return "";
    }

    std::vector<char> base64(base64Len);
    if (!CryptBinaryToStringA(data.data(), data.size(),
        CRYPT_STRING_BASE64 | CRYPT_STRING_NOCRLF, base64.data(), &base64Len)) {
        return "";
    }

    return std::string(base64.data());
}

// ========== Base64解码 ==========
std::vector<uint8_t> Base64Decode(const std::string& base64) {
    if (base64.empty()) return {};

    DWORD dataLen = 0;
    if (!CryptStringToBinaryA(base64.c_str(), base64.length(),
        CRYPT_STRING_BASE64, NULL, &dataLen, NULL, NULL)) {
        return {};
    }

    std::vector<uint8_t> data(dataLen);
    if (!CryptStringToBinaryA(base64.c_str(), base64.length(),
        CRYPT_STRING_BASE64, data.data(), &dataLen, NULL, NULL)) {
        return {};
    }

    return data;
}


// ========== 修改 AES_Encrypt 和 AES_Decrypt 函数 ==========

// 辅助函数：将密钥和IV转换为可导入的格式
std::vector<uint8_t> PrepareKeyBlob(const std::string& key) {
    // PLAINTEXTKEYBLOB 结构
    struct KEYBLOB {
        BLOBHEADER hdr;
        DWORD keySize;
        BYTE keyData[32]; // AES-256需要32字节
    };

    KEYBLOB blob = {};
    blob.hdr.bType = PLAINTEXTKEYBLOB;
    blob.hdr.bVersion = CUR_BLOB_VERSION;
    blob.hdr.reserved = 0;
    blob.hdr.aiKeyAlg = CALG_AES_256;
    blob.keySize = 32;

    // 复制密钥数据
    memcpy(blob.keyData, key.c_str(), (key.length() < 32 ? key.length() : 32));


    std::vector<uint8_t> result((uint8_t*)&blob, (uint8_t*)&blob + sizeof(KEYBLOB));
    return result;
}

// 修改后的加密函数
std::vector<uint8_t> AES_Encrypt(const std::string& plaintext) {
    std::vector<uint8_t> result;

    HCRYPTPROV hProv = 0;
    HCRYPTKEY hKey = 0;

    try {
        // 获取加密上下文
        if (!CryptAcquireContext(&hProv, NULL, NULL, PROV_RSA_AES, CRYPT_VERIFYCONTEXT)) {
            throw std::runtime_error("CryptAcquireContext failed");
        }

        // 准备密钥数据
        auto keyBlob = PrepareKeyBlob(AES_KEY);

        // 直接导入密钥
        if (!CryptImportKey(hProv, keyBlob.data(), keyBlob.size(), 0, 0, &hKey)) {
            throw std::runtime_error("CryptImportKey failed");
        }

        // 设置CBC模式
        DWORD mode = CRYPT_MODE_CBC;
        if (!CryptSetKeyParam(hKey, KP_MODE, (BYTE*)&mode, 0)) {
            throw std::runtime_error("CryptSetKeyParam MODE failed");
        }

        // 设置IV
        if (!CryptSetKeyParam(hKey, KP_IV, (BYTE*)AES_IV.c_str(), 0)) {
            throw std::runtime_error("CryptSetKeyParam IV failed");
        }

        // 准备数据
        std::vector<uint8_t> data(plaintext.begin(), plaintext.end());
        DWORD dataLen = data.size();
        DWORD bufferLen = dataLen + 16; // AES块大小
        data.resize(bufferLen);

        // 加密
        if (!CryptEncrypt(hKey, 0, TRUE, 0, data.data(), &dataLen, bufferLen)) {
            throw std::runtime_error("CryptEncrypt failed");
        }

        data.resize(dataLen);
        result = data;

    }
    catch (...) {
        if (hKey) CryptDestroyKey(hKey);
        if (hProv) CryptReleaseContext(hProv, 0);
        throw;
    }

    if (hKey) CryptDestroyKey(hKey);
    if (hProv) CryptReleaseContext(hProv, 0);

    return result;
}

// 修改后的解密函数
std::string AES_Decrypt(const std::vector<uint8_t>& ciphertext) {
    std::string result;

    HCRYPTPROV hProv = 0;
    HCRYPTKEY hKey = 0;

    try {
        // 获取加密上下文
        if (!CryptAcquireContext(&hProv, NULL, NULL, PROV_RSA_AES, CRYPT_VERIFYCONTEXT)) {
            throw std::runtime_error("CryptAcquireContext failed");
        }

        // 准备密钥数据
        auto keyBlob = PrepareKeyBlob(AES_KEY);

        // 直接导入密钥
        if (!CryptImportKey(hProv, keyBlob.data(), keyBlob.size(), 0, 0, &hKey)) {
            throw std::runtime_error("CryptImportKey failed");
        }

        // 设置CBC模式
        DWORD mode = CRYPT_MODE_CBC;
        if (!CryptSetKeyParam(hKey, KP_MODE, (BYTE*)&mode, 0)) {
            throw std::runtime_error("CryptSetKeyParam MODE failed");
        }

        // 设置IV
        if (!CryptSetKeyParam(hKey, KP_IV, (BYTE*)AES_IV.c_str(), 0)) {
            throw std::runtime_error("CryptSetKeyParam IV failed");
        }

        // 准备数据
        std::vector<uint8_t> data = ciphertext;
        DWORD dataLen = data.size();

        // 解密
        if (!CryptDecrypt(hKey, 0, TRUE, 0, data.data(), &dataLen)) {
            throw std::runtime_error("CryptDecrypt failed");
        }

        result = std::string(data.begin(), data.begin() + dataLen);

    }
    catch (...) {
        if (hKey) CryptDestroyKey(hKey);
        if (hProv) CryptReleaseContext(hProv, 0);
        throw;
    }

    if (hKey) CryptDestroyKey(hKey);
    if (hProv) CryptReleaseContext(hProv, 0);

    return result;
}


















// ========== 旧版伪心跳算法已删除，现在使用 ReplaceHeartbeatDataFromPool ==========

// ========== ?????? 基于 01 0A 00 23 特征的自定义偏移替换函数 ==========
// 在23特征替换前执行，根据用户配置的偏移规则进行替换
// 参数：
//   modifiedData: 要修改的数据（引用，直接修改）
//   poolData: 数据池中的数据
//   gameID: 游戏ID（用于日志）
// 返回：是否有替换发生
bool ApplyPattern23OffsetReplace(
    std::vector<uint8_t>& modifiedData,
    const HeartbeatRecord& poolData,
    const std::string& gameID)
{
    // 调试日志：检查总开关
    if (!g_enablePattern23OffsetReplace) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 总开关未启用");
        return false;
    }

    std::lock_guard<std::mutex> lock(g_pattern23OffsetMutex);

    // 调试日志：检查规则列表
    if (g_pattern23OffsetRules.empty()) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 规则列表为空");
        return false;
    }

    // 统计启用的规则数量
    int enabledCount = 0;
    for (const auto& r : g_pattern23OffsetRules) {
        if (r.enabled) enabledCount++;
    }

    AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 开始处理 | 规则总数:" +
        std::to_string(g_pattern23OffsetRules.size()) + " 启用:" + std::to_string(enabledCount) +
        " | 原始数据:" + std::to_string(modifiedData.size()) + "B 池数据:" + std::to_string(poolData.rawData.size()) + "B");

    if (enabledCount == 0) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 没有启用的规则");
        return false;
    }

    // 在原始数据中找到 01 0A 00 23 特征位置
    std::vector<uint8_t> pattern23 = { 0x01, 0x0a, 0x00, 0x23 };
    int pos23Original = PacketParser::FindPattern(modifiedData, pattern23);

    if (pos23Original == -1) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 原始数据中未找到01 0A 00 23特征");
        return false;
    }

    // 在数据池数据中找到 01 0A 00 23 特征位置
    int pos23Pool = PacketParser::FindPattern(poolData.rawData, pattern23);

    if (pos23Pool == -1) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 数据池数据中未找到01 0A 00 23特征");
        return false;
    }

    AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 特征位置 | 原始pos23=" +
        std::to_string(pos23Original) + " 池pos23=" + std::to_string(pos23Pool));

    bool anyReplaced = false;
    std::string replacedInfo;

    // 遍历所有启用的规则进行替换
    for (size_t i = 0; i < g_pattern23OffsetRules.size(); i++) {
        const auto& rule = g_pattern23OffsetRules[i];

        if (!rule.enabled) {
            AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 规则[" + rule.name + "] 未启用，跳过");
            continue;
        }

        // 计算原始数据中的目标位置
        int targetPosOriginal = pos23Original + rule.offset;
        // 计算数据池中的源位置
        int sourcePosPool = pos23Pool + rule.offset;

        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 规则[" + rule.name +
            "] 计算位置 | offset=" + std::to_string(rule.offset) +
            " len=" + std::to_string(rule.length) +
            " | 目标pos=" + std::to_string(targetPosOriginal) +
            " 源pos=" + std::to_string(sourcePosPool));

        // 边界检查 - 原始数据
        if (targetPosOriginal < 0 || targetPosOriginal + rule.length > static_cast<int>(modifiedData.size())) {
            AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 规则[" + rule.name +
                "] 目标位置越界: pos=" + std::to_string(targetPosOriginal) +
                ", len=" + std::to_string(rule.length) +
                ", dataSize=" + std::to_string(modifiedData.size()));
            continue;
        }

        // 边界检查 - 数据池
        if (sourcePosPool < 0 || sourcePosPool + rule.length > static_cast<int>(poolData.rawData.size())) {
            AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 规则[" + rule.name +
                "] 源位置越界: pos=" + std::to_string(sourcePosPool) +
                ", len=" + std::to_string(rule.length) +
                ", poolSize=" + std::to_string(poolData.rawData.size()));
            continue;
        }

        // 记录替换前的值
        std::stringstream beforeSS, afterSS;
        beforeSS << std::hex << std::uppercase << std::setfill('0');
        afterSS << std::hex << std::uppercase << std::setfill('0');
        for (int j = 0; j < rule.length; j++) {
            beforeSS << std::setw(2) << static_cast<int>(modifiedData[targetPosOriginal + j]);
            afterSS << std::setw(2) << static_cast<int>(poolData.rawData[sourcePosPool + j]);
            if (j < rule.length - 1) {
                beforeSS << " ";
                afterSS << " ";
            }
        }

        // 执行替换：将数据池中对应位置的数据复制到原始数据中
        for (int j = 0; j < rule.length; j++) {
            modifiedData[targetPosOriginal + j] = poolData.rawData[sourcePosPool + j];
        }

        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 规则[" + rule.name +
            "] 替换完成 | 位置" + std::to_string(targetPosOriginal) +
            " | 原值:[" + beforeSS.str() + "] -> 新值:[" + afterSS.str() + "]");

        anyReplaced = true;

        // 记录替换信息
        if (!replacedInfo.empty()) replacedInfo += ", ";
        replacedInfo += rule.name + "(偏移" + std::to_string(rule.offset) + "," +
            std::to_string(rule.length) + "字节)";
    }

    if (anyReplaced) {
        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[23偏移替换|" + gameID + "] 替换成功: " + replacedInfo);
    }

    return anyReplaced;
}

// ========== 09偏移替换函数 ==========
// 支持 length=0 表示从偏移位置到包尾
bool ApplyPattern09OffsetReplace(
    std::vector<uint8_t>& modifiedData,
    const HeartbeatRecord& poolData,
    const std::string& gameID)
{
    if (!g_enablePattern09OffsetReplace) {
        return false;
    }

    std::lock_guard<std::mutex> lock(g_pattern09OffsetMutex);

    if (g_pattern09OffsetRules.empty()) {
        return false;
    }

    // 统计启用的规则数量
    int enabledCount = 0;
    for (const auto& r : g_pattern09OffsetRules) {
        if (r.enabled) enabledCount++;
    }

    if (enabledCount == 0) {
        return false;
    }

    // 在原始数据中找到 01 0A 00 09 特征位置
    std::vector<uint8_t> pattern09 = { 0x01, 0x0a, 0x00, 0x09 };
    int pos09Original = PacketParser::FindPattern(modifiedData, pattern09);

    if (pos09Original == -1) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 原始数据中未找到01 0A 00 09特征");
        return false;
    }

    // 在数据池数据中找到 01 0A 00 09 特征位置
    int pos09Pool = PacketParser::FindPattern(poolData.rawData, pattern09);

    if (pos09Pool == -1) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 数据池数据中未找到01 0A 00 09特征");
        return false;
    }

    AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 特征位置 | 原始pos09=" +
        std::to_string(pos09Original) + " 池pos09=" + std::to_string(pos09Pool));

    bool anyReplaced = false;
    std::string replacedInfo;

    // 遍历所有启用的规则进行替换
    for (size_t i = 0; i < g_pattern09OffsetRules.size(); i++) {
        const auto& rule = g_pattern09OffsetRules[i];

        if (!rule.enabled) {
            continue;
        }

        // 计算原始数据中的目标位置
        int targetPosOriginal = pos09Original + rule.offset;
        // 计算数据池中的源位置
        int sourcePosPool = pos09Pool + rule.offset;

        // 负数长度检查
        if (rule.length < 0) {
            AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 规则[" + rule.name +
                "] 长度无效: " + std::to_string(rule.length));
            continue;
        }

        // 计算实际替换长度
        int actualLength = rule.length;
        if (actualLength == 0) {
            // length=0 表示从偏移位置到包尾
            actualLength = static_cast<int>(modifiedData.size()) - targetPosOriginal;
            if (actualLength <= 0) {
                AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 规则[" + rule.name +
                    "] 偏移位置超出数据范围");
                continue;
            }
            // 同时计算数据池对应长度
            int poolActualLength = static_cast<int>(poolData.rawData.size()) - sourcePosPool;
            if (poolActualLength <= 0) {
                AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 规则[" + rule.name +
                    "] 数据池偏移位置超出范围");
                continue;
            }
            if (poolActualLength < actualLength) {
                actualLength = poolActualLength;  // 使用较小的长度
            }
        }

        // 最终长度检查
        if (actualLength <= 0) {
            AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 规则[" + rule.name +
                "] 计算后长度无效: " + std::to_string(actualLength));
            continue;
        }

        // 边界检查 - 原始数据
        if (targetPosOriginal < 0 || targetPosOriginal + actualLength > static_cast<int>(modifiedData.size())) {
            AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 规则[" + rule.name +
                "] 目标位置越界: pos=" + std::to_string(targetPosOriginal) +
                ", len=" + std::to_string(actualLength) +
                ", dataSize=" + std::to_string(modifiedData.size()));
            continue;
        }

        // 边界检查 - 数据池
        if (sourcePosPool < 0 || sourcePosPool + actualLength > static_cast<int>(poolData.rawData.size())) {
            AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 规则[" + rule.name +
                "] 源位置越界: pos=" + std::to_string(sourcePosPool) +
                ", len=" + std::to_string(actualLength) +
                ", poolSize=" + std::to_string(poolData.rawData.size()));
            continue;
        }

        // 特殊处理 length=0 (到包尾)：需要调整包大小
        if (rule.length == 0) {
            // 保留目标位置之前的数据
            std::vector<uint8_t> beforeTarget(modifiedData.begin(), modifiedData.begin() + targetPosOriginal);
            // 追加数据池中对应位置到包尾的数据
            beforeTarget.insert(beforeTarget.end(),
                poolData.rawData.begin() + sourcePosPool,
                poolData.rawData.end());
            modifiedData = beforeTarget;

            AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 规则[" + rule.name +
                "] 替换完成(到包尾) | 位置" + std::to_string(targetPosOriginal) +
                " | 替换" + std::to_string(poolData.rawData.size() - sourcePosPool) + "字节");

            anyReplaced = true;
            if (!replacedInfo.empty()) replacedInfo += ", ";
            replacedInfo += rule.name + "(偏移" + std::to_string(rule.offset) + ",到包尾)";
        }
        else {
            // 固定长度替换：记录替换前的值
            std::stringstream beforeSS, afterSS;
            beforeSS << std::hex << std::uppercase << std::setfill('0');
            afterSS << std::hex << std::uppercase << std::setfill('0');
            int displayLen = std::min(actualLength, 8);  // 日志最多显示8字节
            for (int j = 0; j < displayLen; j++) {
                beforeSS << std::setw(2) << static_cast<int>(modifiedData[targetPosOriginal + j]);
                afterSS << std::setw(2) << static_cast<int>(poolData.rawData[sourcePosPool + j]);
                if (j < displayLen - 1) {
                    beforeSS << " ";
                    afterSS << " ";
                }
            }
            if (actualLength > 8) {
                beforeSS << "...";
                afterSS << "...";
            }

            // 执行替换：将数据池中对应位置的数据复制到原始数据中
            for (int j = 0; j < actualLength; j++) {
                modifiedData[targetPosOriginal + j] = poolData.rawData[sourcePosPool + j];
            }

            AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 规则[" + rule.name +
                "] 替换完成 | 位置" + std::to_string(targetPosOriginal) +
                " | 原值:[" + beforeSS.str() + "] -> 新值:[" + afterSS.str() + "]");

            anyReplaced = true;
            if (!replacedInfo.empty()) replacedInfo += ", ";
            replacedInfo += rule.name + "(偏移" + std::to_string(rule.offset) + "," +
                std::to_string(actualLength) + "字节)";
        }
    }

    if (anyReplaced) {
        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[09偏移替换|" + gameID + "] 替换成功: " + replacedInfo);
    }

    return anyReplaced;
}

// ========== ?????? 新版伪心跳替换函数（从采集内存池按SOCKS用户名顺序替换）==========
// ?? 改为按SOCKS用户名查找替换数据（而非GameID）
// 替换完成后，该记录从内存池中删除
std::vector<uint8_t> ReplaceHeartbeatDataFromPool(
    const std::vector<uint8_t>& originalData,
    const PacketInfo& originalPacket,
    bool* outSuccess,
    std::string* outPoolGameID)
{
    if (outSuccess) *outSuccess = false;

    PacketInfo reparsedPacket = PacketParser::ParsePacket(originalData);
    std::string gameID = reparsedPacket.gameID;
    std::string socksUsername = originalPacket.socksUsername;  // ?? 使用SOCKS用户名

    if (gameID.empty()) {
        AB_LOG_WARNING("[伪心跳-新版] GameID为空，使用原始数据");
        return originalData;
    }

    // ?? SOCKS用户名为空时，无法按用户名查找
    if (socksUsername.empty()) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳-新版|" + gameID + "] SOCKS用户名为空，无法查找替换数据");
        return originalData;
    }

    // 检查是否符合伪心跳条件
    bool has23Pattern = !reparsedPacket.pattern_01_0a_00_23.empty();
    bool has09Pattern = !reparsedPacket.pattern_01_0a_00_09.empty();
    bool has62Pattern = g_enableHeartbeat62Pattern && !reparsedPacket.pattern_01_0a_00_62.empty();

    if (!has23Pattern || (!has09Pattern && !has62Pattern)) {
        std::string reason = !has23Pattern ? "缺少23特征" : "缺少09或62特征";
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳-新版|" + gameID + "] 不符合替换条件: " + reason);
        return originalData;
    }

    // ===== 新版：替换数量规则（可配置到达后策略）=====
    const std::string replaceKey = HbReplaceRules_MakeKey(false, gameID, socksUsername); // 本函数固定按账号替换
    const bool shouldReplace = HbReplaceRules_ShouldAttemptReplace(
        replaceKey, &g_collectedPool, false, gameID, socksUsername);
    if (!shouldReplace) {
        HbReplaceRules_OnOriginalSentAfterReach(replaceKey);
        return originalData;
    }

    // ===== ?? 从采集内存池中获取对应SOCKS用户名的数据（支持升序/降序）=====
    HeartbeatRecord poolData;
    bool ascending = (g_packetOrderMode == PacketOrderMode::ASCENDING);
    std::string orderModeStr = ascending ? "升序" : "降序";
    if (!g_collectedPool.PopPacketByUsername(socksUsername, poolData, ascending)) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳-新版|" + socksUsername + "] 内存池中无对应用户数据");
        return originalData;
    }

    if (outPoolGameID) *outPoolGameID = poolData.gameID;

    AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳-新版|用户:" + socksUsername + "|ID:" + gameID + "] 从内存池获取数据(" + orderModeStr + ") | 剩余: " +
        std::to_string(g_collectedPool.GetCountByUsername(socksUsername)) + " 条");

    // ===== 开始替换 =====
    std::vector<uint8_t> modifiedData = originalData;
    bool replaced23 = false;
    bool replaced09 = false;
    bool replaced62 = false;
    bool replaced0A92 = false;  // 新增：0A92特征替换标志
    bool replacedOffset = false;  // 新增：23偏移替换标志

    // 09和62特征互补逻辑
    std::vector<uint8_t> actual09Data = poolData.pattern09Data;
    std::vector<uint8_t> actual62Data = poolData.pattern62Data;

    if (actual09Data.empty() && !actual62Data.empty()) {
        actual09Data = actual62Data;
    }
    if (actual62Data.empty() && !actual09Data.empty()) {
        actual62Data = actual09Data;
    }

    // ===== ?????? 第一步：基于 01 0A 00 23 特征的自定义偏移替换（在所有其他替换之前）=====
    // 这一步使用用户配置的偏移规则，从数据池中提取对应位置的数据替换到原始包中
    replacedOffset = ApplyPattern23OffsetReplace(modifiedData, poolData, gameID);

    // ===== 第1.5步：基于 01 0A 00 09 特征的自定义偏移替换 =====
    // 如果启用了09偏移替换且有规则，则使用09偏移替换代替原有的09替换逻辑
    bool used09OffsetReplace = ApplyPattern09OffsetReplace(modifiedData, poolData, gameID);
    if (used09OffsetReplace) {
        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|" + gameID + "] 09偏移替换已完成");
        replaced09 = true;  // 标记09已被替换
    }

    // 替换 01 0a 00 23 特征数据（12字节）
    if (!reparsedPacket.pattern_01_0a_00_23.empty() && !poolData.pattern23Data.empty()) {
        std::vector<uint8_t> pattern = { 0x01, 0x0a, 0x00, 0x23 };
        int pos = PacketParser::FindPattern(modifiedData, pattern);

        if (pos != -1) {
            int startPos = pos - 8;
            if (startPos >= 0 && startPos + 12 <= modifiedData.size()) {
                // 先复制12字节数据
                for (size_t i = 0; i < poolData.pattern23Data.size() && i < 12; i++) {
                    modifiedData[startPos + i] = poolData.pattern23Data[i];
                }
                replaced23 = true;

                // ===== 动态计算模式：计算长度值并写入 =====
                if (g_pattern23Mode == PATTERN23_DYNAMIC) {
                    // 计算范围：从23特征前5字节到包尾
                    int lengthStartPos = pos - 6;  // 01 0A 00 23 前5字节位置
                    int packetEndPos = static_cast<int>(modifiedData.size()) - 1;

                    if (lengthStartPos >= 0 && lengthStartPos < static_cast<int>(modifiedData.size())) {
                        int calculatedLength = packetEndPos - lengthStartPos + 1;

                        uint16_t lengthValue = static_cast<uint16_t>(calculatedLength);
                        uint8_t highByte = (lengthValue >> 8) & 0xFF;
                        uint8_t lowByte = lengthValue & 0xFF;

                        std::string writeLog;

                        // 写入第一处（由g_pattern23DynamicOffset控制）
                        int writeOffset = g_pattern23DynamicOffset;
                        if (writeOffset >= 0 && writeOffset < 7 && startPos + writeOffset + 1 < static_cast<int>(modifiedData.size())) {
                            uint8_t origHigh1 = modifiedData[startPos + writeOffset];
                            uint8_t origLow1 = modifiedData[startPos + writeOffset + 1];

                            modifiedData[startPos + writeOffset] = highByte;
                            modifiedData[startPos + writeOffset + 1] = lowByte;

                            char buffer[256];
                            sprintf_s(buffer,
                                "  位置1 (偏移%d): 字节%d-%d, 原值[%02X %02X] -> 新值[%02X %02X]",
                                writeOffset,
                                startPos + writeOffset,
                                startPos + writeOffset + 1,
                                origHigh1, origLow1,
                                highByte, lowByte);
                            writeLog += std::string(buffer) + "\n";
                        }

                        // 写入第二处（固定偏移6）
                        const int fixedOffset = 6;
                        if (startPos + fixedOffset + 1 < static_cast<int>(modifiedData.size())) {
                            uint8_t origHigh2 = modifiedData[startPos + fixedOffset];
                            uint8_t origLow2 = modifiedData[startPos + fixedOffset + 1];

                            modifiedData[startPos + fixedOffset] = highByte;
                            modifiedData[startPos + fixedOffset + 1] = lowByte;

                            char buffer[256];
                            sprintf_s(buffer,
                                "  位置2 (偏移%d): 字节%d-%d, 原值[%02X %02X] -> 新值[%02X %02X]",
                                fixedOffset,
                                startPos + fixedOffset,
                                startPos + fixedOffset + 1,
                                origHigh2, origLow2,
                                highByte, lowByte);
                            writeLog += std::string(buffer);
                        }

                        char logBuffer[1024];
                        sprintf_s(logBuffer,
                            "[伪心跳|%s] 动态计算 01 0A 00 23 长度:\n"
                            "  计算范围: 字节%d (01 0A 00 23 前5字节) -> 字节%d (包尾)\n"
                            "  计算长度: %d 字节 (0x%04X)\n"
                            "  写入两处:\n%s",
                            gameID.c_str(),
                            lengthStartPos,
                            packetEndPos,
                            calculatedLength, lengthValue,
                            writeLog.c_str());
                        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, std::string(logBuffer));
                    }
                }
            }
        }
    }

    // 替换 00 00 0A 92 特征数据（4字节，位于特征码后偏移4位）
    if (!reparsedPacket.pattern_00_00_0a_92.empty() && !poolData.pattern0A92Data.empty()) {
        std::vector<uint8_t> pattern0A92 = { 0x00, 0x00, 0x0a, 0x92 };
        int pos0A92 = PacketParser::FindPattern(modifiedData, pattern0A92);

        if (pos0A92 != -1) {
            // 往后偏移4位（跳过 00 00 0A 92 本身），替换4字节
            int startPos0A92 = pos0A92 + 4;
            if (startPos0A92 + 4 <= static_cast<int>(modifiedData.size())) {
                for (size_t i = 0; i < poolData.pattern0A92Data.size() && i < 4; i++) {
                    modifiedData[startPos0A92 + i] = poolData.pattern0A92Data[i];
                }
                replaced0A92 = true;
            }
        }
    }

    // ===== 09特征替换已移除，改用09偏移替换功能 =====
    // 原有的01 0a 00 09特征替换逻辑已删除
    // 如需09特征替换，请使用09偏移替换功能（ApplyPattern09OffsetReplace）

    // 替换 01 0a 00 62 特征数据
    if (g_enableHeartbeat62Pattern && !reparsedPacket.pattern_01_0a_00_62.empty() && !actual62Data.empty()) {
        std::vector<uint8_t> pattern62 = { 0x01, 0x0a, 0x00, 0x62 };
        int pos62 = PacketParser::FindPattern(modifiedData, pattern62);

        if (pos62 != -1) {
            int startPos62 = pos62 - 8;
            if (startPos62 >= 0) {
                std::vector<uint8_t> beforePattern62(modifiedData.begin(), modifiedData.begin() + startPos62);
                beforePattern62.insert(beforePattern62.end(), actual62Data.begin(), actual62Data.end());
                modifiedData = beforePattern62;
                replaced62 = true;
            }
        }
    }

    // 更新包头长度字段
    if (modifiedData.size() >= 5) {
        uint16_t finalSize = static_cast<uint16_t>(modifiedData.size());
        modifiedData[3] = (finalSize >> 8) & 0xFF;
        modifiedData[4] = finalSize & 0xFF;
    }

    if (replacedOffset || replaced23 || replaced09 || replaced62 || replaced0A92) {
        if (outSuccess) *outSuccess = true;
        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳-新版|" + gameID + "] 替换成功 | " +
            "偏移:" + (replacedOffset ? "是" : "否") +
            " 23:" + (replaced23 ? "是" : "否") +
            " 0A92:" + (replaced0A92 ? "是" : "否") +
            " 09:" + (replaced09 ? "是" : "否") +
            " 62:" + (replaced62 ? "是" : "否") + " | 原始:" +
            std::to_string(originalData.size()) + "B -> 修改:" +
            std::to_string(modifiedData.size()) + "B");
    }

    // 本次确实走了"伪心跳替换"路径：推进替换数量规则计数
    HbReplaceRules_OnFakeSentSuccessfully(replaceKey, &g_collectedPool, false, gameID, socksUsername);

    return modifiedData;
}


// ========== ?????? 固定偏移替换模式函数 ==========
// 算法描述：
// 1. 使用固定偏移值作为分割点
// 2. 保留从包头到固定偏移位置的数据不变
// 3. ?? 从数据池中取对应SOCKS用户名的数据，替换固定偏移之后的部分
// 4. 重新计算包大小
std::vector<uint8_t> ReplaceWithFixedOffset(
    const std::vector<uint8_t>& originalData,
    const PacketInfo& originalPacket,
    bool* outSuccess,
    std::string* outPoolGameID)
{
    if (outSuccess) *outSuccess = false;

    PacketInfo reparsedPacket = PacketParser::ParsePacket(originalData);
    std::string gameID = reparsedPacket.gameID;
    std::string socksUsername = originalPacket.socksUsername;  // ?? 使用SOCKS用户名

    if (gameID.empty()) {
        AB_LOG_WARNING("[固定偏移替换] GameID为空，使用原始数据");
        return originalData;
    }

    // ?? SOCKS用户名为空时，无法按用户名查找
    if (socksUsername.empty()) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[固定偏移替换|" + gameID + "] SOCKS用户名为空，无法查找替换数据");
        return originalData;
    }

    // 获取固定偏移值
    int fixedOffset = g_fixedReplaceOffset;

    // 检查原始数据长度是否足够
    if (static_cast<int>(originalData.size()) <= fixedOffset) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[固定偏移替换|" + gameID + "] 原始数据长度(" +
            std::to_string(originalData.size()) + ")小于偏移值(" + std::to_string(fixedOffset) + ")，跳过");
        return originalData;
    }

    // ===== ?? 从采集内存池中获取对应SOCKS用户名的数据（支持升序/降序）=====
    HeartbeatRecord poolData;
    bool ascending = (g_packetOrderMode == PacketOrderMode::ASCENDING);
    std::string orderModeStr = ascending ? "升序" : "降序";
    if (!g_collectedPool.PopPacketByUsername(socksUsername, poolData, ascending)) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[固定偏移替换|" + socksUsername + "] 内存池中无对应用户数据");
        return originalData;
    }

    if (outPoolGameID) *outPoolGameID = poolData.gameID;

    AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[固定偏移替换|用户:" + socksUsername + "] 从内存池获取数据(" + orderModeStr + ") | 剩余: " +
        std::to_string(g_collectedPool.GetCountByUsername(socksUsername)) + " 条");

    // 检查数据池数据长度是否足够
    if (static_cast<int>(poolData.rawData.size()) <= fixedOffset) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[固定偏移替换|" + socksUsername + "] 数据池数据长度(" +
            std::to_string(poolData.rawData.size()) + ")小于偏移值(" + std::to_string(fixedOffset) + ")");
        return originalData;
    }

    AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[固定偏移替换|用户:" + socksUsername + "|ID:" + gameID + "] 从内存池获取数据成功 | 剩余: " +
        std::to_string(g_collectedPool.GetCountByUsername(socksUsername)) + " 条");

    // ===== 开始替换 =====
    // 保留原始数据前 fixedOffset 字节
    int keepLength = fixedOffset;

    // 构建新的数据包
    std::vector<uint8_t> modifiedData;

    // 1. 复制原始数据的前半部分（保留前 fixedOffset 字节）
    modifiedData.insert(modifiedData.end(), originalData.begin(), originalData.begin() + keepLength);

    // 2. 追加数据池中固定偏移之后的数据
    modifiedData.insert(modifiedData.end(), poolData.rawData.begin() + fixedOffset, poolData.rawData.end());

    // ===== ?????? 新增：基于 01 0A 00 23 特征的自定义偏移替换 =====
    // 这一步使用用户配置的偏移规则，从数据池中提取对应位置的数据替换到当前包中
    bool replacedOffset = ApplyPattern23OffsetReplace(modifiedData, poolData, gameID);

    // ===== 新增：基于 01 0A 00 09 特征的自定义偏移替换 =====
    bool replaced09Offset = ApplyPattern09OffsetReplace(modifiedData, poolData, gameID);
    if (replaced09Offset) {
        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[固定偏移替换|" + gameID + "] 09偏移替换已完成");
    }

    // 3. 更新包头长度字段（假设包头格式为: [01命令][00 00保留][总长度2字节]）
    if (modifiedData.size() >= 5) {
        uint16_t finalSize = static_cast<uint16_t>(modifiedData.size());
        modifiedData[3] = (finalSize >> 8) & 0xFF;
        modifiedData[4] = finalSize & 0xFF;
    }

    if (outSuccess) *outSuccess = true;

    AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[固定偏移替换|" + gameID + "] 替换成功 | " +
        "偏移:" + std::to_string(fixedOffset) + " 保留:" + std::to_string(keepLength) + "B" +
        " 23偏移替换:" + (replacedOffset ? "是" : "否") + " | " +
        "原始:" + std::to_string(originalData.size()) + "B -> 修改:" + std::to_string(modifiedData.size()) + "B");

    return modifiedData;
}


// ========== ?????? 正确的伪心跳逻辑（从实例内存池替换）==========
// ?? 改为按SOCKS用户名查找替换数据（而非GameID）
// 包含23自定义偏移替换功能
static std::vector<uint8_t> ReplaceFromInstancePool(
    const std::vector<uint8_t>& originalData,
    const PacketInfo& packet,
    CollectedPacketPool* sourcePool,
    bool enableHeartbeat62Pattern,
    bool* outSuccess,
    HeartbeatReplaceOutcome* outOutcome) {

    if (outSuccess) *outSuccess = false;
    if (outOutcome) *outOutcome = HeartbeatReplaceOutcome::NotReplaced;

    if (!sourcePool) {
        AB_LOG_WARNING("[伪心跳] 内存池未连接");
        return originalData;
    }

    PacketInfo reparsedPacket = PacketParser::ParsePacket(originalData);
    std::string gameID = reparsedPacket.gameID;
    std::string socksUsername = packet.socksUsername;  // ?? 使用SOCKS用户名

    if (gameID.empty()) {
        return originalData;
    }

    // ?? SOCKS用户名为空时，无法按用户名查找
    if (socksUsername.empty()) {
        AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|" + gameID + "] SOCKS用户名为空，无法查找替换数据");
        return originalData;
    }

    // 检查是否符合伪心跳条件
    bool has23 = !reparsedPacket.pattern_01_0a_00_23.empty();
    bool has09 = !reparsedPacket.pattern_01_0a_00_09.empty();
    bool has62 = enableHeartbeat62Pattern && !reparsedPacket.pattern_01_0a_00_62.empty();

    if (!has23 || (!has09 && !has62)) {
        if (outOutcome) *outOutcome = HeartbeatReplaceOutcome::NotReplaced;
        return originalData;
    }

    // ===== 新版：替换数量规则（可配置到达后策略）=====
    const std::string replaceKey = HbReplaceRules_MakeKey(g_useSameAlgorithm, gameID, socksUsername);
    const bool shouldReplace = HbReplaceRules_ShouldAttemptReplace(
        replaceKey, sourcePool, g_useSameAlgorithm, gameID, socksUsername);

    if (!shouldReplace) {
        // 到达后策略可能要求"原包段"推进计数
        HbReplaceRules_OnOriginalSentAfterReach(replaceKey);
        if (outOutcome) *outOutcome = HeartbeatReplaceOutcome::SkippedByRule;
        return originalData;
    }

    // ?? 根据算法选择使用不同的数据包查找方式
    HeartbeatRecord poolData;
    bool found = false;

    // ?? 根据顺序模式决定是升序还是降序
    bool ascending = (g_packetOrderMode == PacketOrderMode::ASCENDING);
    std::string orderModeStr = ascending ? "升序" : "降序";

    if (g_useSameAlgorithm) {
        // 同号算法：按游戏ID查找
        found = sourcePool->PopPacketByGameID(gameID, poolData, ascending);
        if (found) {
            AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|ID:" + gameID + "] 从内存池获取数据(" + orderModeStr + ") | 剩余: " +
                std::to_string(sourcePool->GetCountByGameID(gameID)) + " 条");
        } else {
            AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|" + gameID + "] 内存池中无对应游戏ID数据");
            if (outOutcome) *outOutcome = HeartbeatReplaceOutcome::NotReplaced;
            return originalData;
        }
    } else {
        // 异号算法：按SOCKS账号查找
        if (socksUsername.empty()) {
            AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|" + gameID + "] SOCKS用户名为空，无法查找替换数据");
            return originalData;
        }

        found = sourcePool->PopPacketByUsername(socksUsername, poolData, ascending);
        if (found) {
            AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|用户:" + socksUsername + "|ID:" + gameID + "] 从内存池获取数据(" + orderModeStr + ") | 剩余: " +
                std::to_string(sourcePool->GetCountByUsername(socksUsername)) + " 条");
        } else {
            AB_LOG_WARNING_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|" + socksUsername + "] 内存池中无对应用户数据");
            if (outOutcome) *outOutcome = HeartbeatReplaceOutcome::NotReplaced;
            return originalData;
        }
    }

    // 计数由 HbReplaceRules_OnFakeSentSuccessfully 在"确实发出伪包"后推进

    // 开始替换
    std::vector<uint8_t> modifiedData = originalData;
    bool replaced23 = false;
    bool replaced09 = false;
    bool replaced62 = false;
    bool replacedOffset = false;

    // 09和62特征互补逻辑
    std::vector<uint8_t> actual09Data = poolData.pattern09Data;
    std::vector<uint8_t> actual62Data = poolData.pattern62Data;

    if (actual09Data.empty() && !actual62Data.empty()) {
        actual09Data = actual62Data;
    }
    if (actual62Data.empty() && !actual09Data.empty()) {
        actual62Data = actual09Data;
    }

    // ===== ?????? 第一步：基于 01 0A 00 23 特征的自定义偏移替换（在所有其他替换之前）=====
    replacedOffset = ApplyPattern23OffsetReplace(modifiedData, poolData, gameID);

    // ===== 第1.5步：基于 01 0A 00 09 特征的自定义偏移替换 =====
    bool used09OffsetReplace2 = ApplyPattern09OffsetReplace(modifiedData, poolData, gameID);
    if (used09OffsetReplace2) {
        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|" + gameID + "] 09偏移替换已完成");
        replaced09 = true;  // 标记09已被替换
    }

    // 替换23特征数据（12字节）
    if (!reparsedPacket.pattern_01_0a_00_23.empty() && !poolData.pattern23Data.empty()) {
        std::vector<uint8_t> pattern = { 0x01, 0x0a, 0x00, 0x23 };
        int pos = PacketParser::FindPattern(modifiedData, pattern);

        if (pos != -1) {
            int startPos = pos - 8;
            if (startPos >= 0 && startPos + 12 <= static_cast<int>(modifiedData.size())) {
                for (size_t i = 0; i < poolData.pattern23Data.size() && i < 12; i++) {
                    modifiedData[startPos + i] = poolData.pattern23Data[i];
                }
                replaced23 = true;

                // ===== 动态计算模式：计算长度值并写入 =====
                if (g_pattern23Mode == PATTERN23_DYNAMIC) {
                    // 计算范围：从23特征前5字节到包尾
                    int lengthStartPos = pos - 6;  // 01 0A 00 23 前5字节位置
                    int packetEndPos = static_cast<int>(modifiedData.size()) - 1;

                    if (lengthStartPos >= 0 && lengthStartPos < static_cast<int>(modifiedData.size())) {
                        int calculatedLength = packetEndPos - lengthStartPos + 1;

                        uint16_t lengthValue = static_cast<uint16_t>(calculatedLength);
                        uint8_t highByte = (lengthValue >> 8) & 0xFF;
                        uint8_t lowByte = lengthValue & 0xFF;

                        std::string writeLog;

                        // 写入第一处（由g_pattern23DynamicOffset控制）
                        int writeOffset = g_pattern23DynamicOffset;
                        if (writeOffset >= 0 && writeOffset < 7 && startPos + writeOffset + 1 < static_cast<int>(modifiedData.size())) {
                            uint8_t origHigh1 = modifiedData[startPos + writeOffset];
                            uint8_t origLow1 = modifiedData[startPos + writeOffset + 1];

                            modifiedData[startPos + writeOffset] = highByte;
                            modifiedData[startPos + writeOffset + 1] = lowByte;

                            char buffer[256];
                            sprintf_s(buffer,
                                "  位置1 (偏移%d): 字节%d-%d, 原值[%02X %02X] -> 新值[%02X %02X]",
                                writeOffset,
                                startPos + writeOffset,
                                startPos + writeOffset + 1,
                                origHigh1, origLow1,
                                highByte, lowByte);
                            writeLog += std::string(buffer) + "\n";
                        }

                        // 写入第二处（固定偏移6）
                        const int fixedOffset = 6;
                        if (startPos + fixedOffset + 1 < static_cast<int>(modifiedData.size())) {
                            uint8_t origHigh2 = modifiedData[startPos + fixedOffset];
                            uint8_t origLow2 = modifiedData[startPos + fixedOffset + 1];

                            modifiedData[startPos + fixedOffset] = highByte;
                            modifiedData[startPos + fixedOffset + 1] = lowByte;

                            char buffer[256];
                            sprintf_s(buffer,
                                "  位置2 (偏移%d): 字节%d-%d, 原值[%02X %02X] -> 新值[%02X %02X]",
                                fixedOffset,
                                startPos + fixedOffset,
                                startPos + fixedOffset + 1,
                                origHigh2, origLow2,
                                highByte, lowByte);
                            writeLog += std::string(buffer);
                        }

                        AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|" + gameID + "] 动态计算长度写入:\n" +
                            "  计算范围: 字节" + std::to_string(lengthStartPos) + " 到 " + std::to_string(packetEndPos) + "\n" +
                            "  计算长度: " + std::to_string(calculatedLength) + " (0x" +
                            [&]() { char buf[16]; sprintf_s(buf, "%04X", lengthValue); return std::string(buf); }() + ")\n" +
                            writeLog);
                    }
                }
            }
        }
    }

    // ===== 09特征替换已移除，改用09偏移替换功能 =====
    // 原有的09特征替换逻辑已删除，如需09特征替换请使用ApplyPattern09OffsetReplace

    // 替换62特征数据
    if (enableHeartbeat62Pattern && !reparsedPacket.pattern_01_0a_00_62.empty() && !actual62Data.empty()) {
        std::vector<uint8_t> pattern62 = { 0x01, 0x0a, 0x00, 0x62 };
        int pos62 = PacketParser::FindPattern(modifiedData, pattern62);

        if (pos62 != -1) {
            int startPos62 = pos62 - 8;
            if (startPos62 >= 0) {
                std::vector<uint8_t> beforePattern62(modifiedData.begin(), modifiedData.begin() + startPos62);
                beforePattern62.insert(beforePattern62.end(), actual62Data.begin(), actual62Data.end());
                modifiedData = beforePattern62;
                replaced62 = true;
            }
        }
    }

    // ===== CRC32 自动计算和替换 =====
    // 计算范围：从 01 0A 00 23 前 6 字节位置到包尾
    // 写入位置：01 00 09 前 4 字节
    if (g_enableCRC32AutoCalc) {
        std::vector<uint8_t> pattern23 = { 0x01, 0x0a, 0x00, 0x23 };
        std::vector<uint8_t> pattern0109 = { 0x01, 0x00, 0x09 };

        int pos23 = PacketParser::FindPattern(modifiedData, pattern23);
        int pos0109 = PacketParser::FindPattern(modifiedData, pattern0109);

        if (pos23 != -1 && pos0109 != -1) {
            // CRC 计算起始位置：01 0A 00 23 前 6 字节
            int crcStartPos = pos23 - 6;
            // CRC 计算结束位置：包尾
            int crcEndPos = static_cast<int>(modifiedData.size()) - 1;
            // CRC 写入位置：01 00 09 前 4 字节
            int crcWritePos = pos0109 - 4;

            if (crcStartPos >= 0 && crcWritePos >= 0 && crcWritePos + 3 < static_cast<int>(modifiedData.size())) {
                // 计算 CRC32
                uint8_t crc0, crc1, crc2, crc3;
                CalculateCRC32(modifiedData, crcStartPos, crcEndPos, crc0, crc1, crc2, crc3);

                // 记录原始值
                uint8_t orig0 = modifiedData[crcWritePos];
                uint8_t orig1 = modifiedData[crcWritePos + 1];
                uint8_t orig2 = modifiedData[crcWritePos + 2];
                uint8_t orig3 = modifiedData[crcWritePos + 3];

                // 写入 CRC32 值（大端序：crc3 crc2 crc1 crc0）
                modifiedData[crcWritePos] = crc3;
                modifiedData[crcWritePos + 1] = crc2;
                modifiedData[crcWritePos + 2] = crc1;
                modifiedData[crcWritePos + 3] = crc0;

                char logBuffer[512];
                sprintf_s(logBuffer,
                    "[CRC32|%s] 自动计算完成:\n"
                    "  计算范围: 字节%d (01 0A 00 23前6位) -> 字节%d (包尾)\n"
                    "  写入位置: 字节%d-%d (01 00 09前4位)\n"
                    "  原始值: [%02X %02X %02X %02X] -> CRC32: [%02X %02X %02X %02X]",
                    gameID.c_str(),
                    crcStartPos, crcEndPos,
                    crcWritePos, crcWritePos + 3,
                    orig0, orig1, orig2, orig3,
                    crc3, crc2, crc1, crc0);
                AB_LOG_INFO(std::string(logBuffer));
            }
            else {
                AB_LOG_WARNING("[CRC32|" + gameID + "] 计算失败: 位置不足 (23位置:" +
                    std::to_string(pos23) + ", 0109位置:" + std::to_string(pos0109) + ")");
            }
        }
        else {
            if (pos23 == -1) {
                AB_LOG_WARNING("[CRC32|" + gameID + "] 计算失败: 未找到 01 0A 00 23 特征");
            }
            if (pos0109 == -1) {
                AB_LOG_WARNING("[CRC32|" + gameID + "] 计算失败: 未找到 01 00 09 特征");
            }
        }
    }

    // 更新包头长度字段
    if (modifiedData.size() >= 5) {
        uint16_t finalSize = static_cast<uint16_t>(modifiedData.size());
        modifiedData[3] = (finalSize >> 8) & 0xFF;
        modifiedData[4] = finalSize & 0xFF;
    }

    if (outSuccess) *outSuccess = true;

    AB_LOG_INFO_CAT(LOG_CAT_HEARTBEAT_REPLACE, "[伪心跳|" + gameID + "] 替换成功 | " +
        "偏移:" + (replacedOffset ? "是" : "否") +
        " 23:" + (replaced23 ? "是" : "否") +
        " 09:" + (replaced09 ? "是" : "否") +
        " 62:" + (replaced62 ? "是" : "否") +
        " | 原始:" + std::to_string(originalData.size()) +
        "B -> 修改:" + std::to_string(modifiedData.size()) + "B");

    // 本次确实消费了数据池记录：推进"伪包"计数，并标记 outcome
    HbReplaceRules_OnFakeSentSuccessfully(replaceKey, sourcePool, g_useSameAlgorithm, gameID, socksUsername);
    if (outOutcome) *outOutcome = HeartbeatReplaceOutcome::Replaced;

    return modifiedData;
}



























