// ========== 在文件开头的全局变量区域添加 ==========
// 日历选择器状态
struct CalendarState {
    int year;
    int month;
    int day;
    int hour;
    int minute;
    int second;
    bool showCalendar;

    CalendarState() : year(2025), month(1), day(1),
        hour(23), minute(59), second(59),
        showCalendar(false) {
        // 初始化为当前日期
        auto now = std::chrono::system_clock::now();
        auto time = std::chrono::system_clock::to_time_t(now);
        struct tm timeinfo;
        localtime_s(&timeinfo, &time);
        year = timeinfo.tm_year + 1900;
        month = timeinfo.tm_mon + 1;
        day = timeinfo.tm_mday;
    }
};

static CalendarState g_newAccountCalendar;   // 新增账号的日历
static CalendarState g_editAccountCalendar;  // 编辑账号的日历

// ========== 日历辅助函数 ==========
// 判断是否为闰年
bool IsLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// 获取某月的天数
int GetDaysInMonth(int year, int month) {
    static const int days[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (month == 2 && IsLeapYear(year)) {
        return 29;
    }
    return days[month - 1];
}

// 获取某月第一天是星期几 (0=星期日, 1=星期一, ..., 6=星期六)
int GetFirstDayOfWeek(int year, int month) {
    // 使用蔡勒公式 (Zeller's formula)
    int m = month;
    int y = year;
    if (m < 3) {
        m += 12;
        y--;
    }
    int c = y / 100;
    y = y % 100;
    int w = (y + y / 4 + c / 4 - 2 * c + (26 * (m + 1)) / 10) % 7;
    if (w < 0) w += 7;
    return w;
}

// 格式化日历日期为字符串
std::string FormatCalendarDate(const CalendarState& cal) {
    char buffer[32];
    sprintf_s(buffer, "%04d-%02d-%02d %02d:%02d:%02d",
        cal.year, cal.month, cal.day,
        cal.hour, cal.minute, cal.second);
    return std::string(buffer);
}

// ========== 渲染日历选择器 ==========
void RenderCalendarPicker(CalendarState& calendar, char* outputBuffer, size_t bufferSize,
    const char* windowId) {
    if (!calendar.showCalendar) return;

    ImGui::SetNextWindowSize(ImVec2(420, 520), ImGuiCond_FirstUseEver);

    char windowTitle[64];
    sprintf_s(windowTitle, "选择日期##%s", windowId);

    if (ImGuiGBK::Begin(windowTitle, &calendar.showCalendar, ImGuiWindowFlags_NoResize)) {

        // ========== 年月选择 ==========
        ImGui::SeparatorText(ImGuiText::U("选择年月"));

        // 年份选择
        ImGuiGBK::Text("年份:");
        ImGui::SameLine(60);
        if (ImGui::Button("<##year")) {
            if (calendar.year > 2000) calendar.year--;
        }
        ImGui::SameLine();
        ImGui::SetNextItemWidth(100);
        ImGui::InputInt("##year_input", &calendar.year, 0, 0);
        if (calendar.year < 2000) calendar.year = 2000;
        if (calendar.year > 2100) calendar.year = 2100;
        ImGui::SameLine();
        if (ImGui::Button(">##year")) {
            if (calendar.year < 2100) calendar.year++;
        }

        // 月份选择
        ImGuiGBK::Text("月份:");
        ImGui::SameLine(60);
        if (ImGui::Button("<##month")) {
            calendar.month--;
            if (calendar.month < 1) {
                calendar.month = 12;
                calendar.year--;
            }
        }
        ImGui::SameLine();
        ImGui::SetNextItemWidth(100);
        ImGui::InputInt("##month_input", &calendar.month, 0, 0);
        if (calendar.month < 1) calendar.month = 1;
        if (calendar.month > 12) calendar.month = 12;
        ImGui::SameLine();
        if (ImGui::Button(">##month")) {
            calendar.month++;
            if (calendar.month > 12) {
                calendar.month = 1;
                calendar.year++;
            }
        }

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // ========== 日历网格 ==========
        ImGui::SeparatorText(ImGuiText::U("选择日期"));

        // 星期标题
        const char* weekDays[] = { "日", "一", "二", "三", "四", "五", "六" };
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(1.0f, 1.0f, 0.0f, 1.0f));
        for (int i = 0; i < 7; i++) {
            ImGuiGBK::Text("%s", weekDays[i]);
            if (i < 6) ImGui::SameLine(60.0f + i * 50.0f);
        }
        ImGui::PopStyleColor();

        ImGui::Spacing();

        // 日期网格
        int daysInMonth = GetDaysInMonth(calendar.year, calendar.month);
        int firstDayOfWeek = GetFirstDayOfWeek(calendar.year, calendar.month);

        ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(4, 4));

        int dayCounter = 1;
        for (int week = 0; week < 6; week++) {
            for (int dayOfWeek = 0; dayOfWeek < 7; dayOfWeek++) {
                if (dayOfWeek > 0) ImGui::SameLine();

                int cellIndex = week * 7 + dayOfWeek;

                // 前面的空白天
                if (cellIndex < firstDayOfWeek || dayCounter > daysInMonth) {
                    ImGui::InvisibleButton("##empty", ImVec2(45, 35));
                    continue;
                }

                char dayLabel[16];
                sprintf_s(dayLabel, "%d##day%d", dayCounter, dayCounter);

                bool isSelected = (dayCounter == calendar.day);

                if (isSelected) {
                    ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.2f, 0.6f, 1.0f, 1.0f));
                }
                else {
                    ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.3f, 0.3f, 0.35f, 1.0f));
                }

                if (ImGui::Button(dayLabel, ImVec2(45, 35))) {
                    calendar.day = dayCounter;
                }

                ImGui::PopStyleColor();

                dayCounter++;
            }

            if (dayCounter > daysInMonth) break;
        }

        ImGui::PopStyleVar();

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // ========== 时间选择 ==========
        ImGui::SeparatorText(ImGuiText::U("选择时间"));

        ImGuiGBK::Text("时间:");
        ImGui::SameLine(60);

        ImGui::SetNextItemWidth(60);
        ImGui::InputInt("##hour", &calendar.hour, 0, 0);
        if (calendar.hour < 0) calendar.hour = 0;
        if (calendar.hour > 23) calendar.hour = 23;

        ImGui::SameLine();
        ImGuiGBK::Text(":");
        ImGui::SameLine();

        ImGui::SetNextItemWidth(60);
        ImGui::InputInt("##minute", &calendar.minute, 0, 0);
        if (calendar.minute < 0) calendar.minute = 0;
        if (calendar.minute > 59) calendar.minute = 59;

        ImGui::SameLine();
        ImGuiGBK::Text(":");
        ImGui::SameLine();

        ImGui::SetNextItemWidth(60);
        ImGui::InputInt("##second", &calendar.second, 0, 0);
        if (calendar.second < 0) calendar.second = 0;
        if (calendar.second > 59) calendar.second = 59;

        ImGui::Spacing();

        // 快捷时间按钮
        if (ImGuiGBK::Button("23:59:59##quick_time", ImVec2(100, 0))) {
            calendar.hour = 23;
            calendar.minute = 59;
            calendar.second = 59;
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button("00:00:00##quick_time2", ImVec2(100, 0))) {
            calendar.hour = 0;
            calendar.minute = 0;
            calendar.second = 0;
        }

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // ========== 底部按钮 ==========
        ImGuiGBK::TextColored(ImVec4(0.5f, 1.0f, 1.0f, 1.0f),
            "已选择: %04d-%02d-%02d %02d:%02d:%02d",
            calendar.year, calendar.month, calendar.day,
            calendar.hour, calendar.minute, calendar.second);

        ImGui::Spacing();

        if (ImGuiGBK::Button("确认选择##confirm", ImVec2(120, 30))) {
            std::string dateStr = FormatCalendarDate(calendar);
            strcpy_s(outputBuffer, bufferSize, dateStr.c_str());
            calendar.showCalendar = false;
        }

        ImGui::SameLine();
        if (ImGuiGBK::Button("清空(永不过期)##clear", ImVec2(150, 30))) {
            outputBuffer[0] = '\0';
            calendar.showCalendar = false;
        }

        ImGui::SameLine();
        if (ImGuiGBK::Button("取消##cancel", ImVec2(80, 30))) {
            calendar.showCalendar = false;
        }

        ImGui::End();
    }
}
