// 渲染白名单编辑窗口
void RenderHeartbeatWhitelistEditWindow(bool& needsRedraw) {
    if (!g_showHeartbeatWhitelistEditWindow) return;

    ImGui::SetNextWindowSize(ImVec2(750, 400), ImGuiCond_FirstUseEver);

    std::string windowTitle = g_heartbeatWhitelistIsNewRule ? "新建白名单规则##hb_whitelist_edit" : "编辑白名单规则##hb_whitelist_edit";
    if (ImGui::Begin(ImGuiText::U(windowTitle.c_str()), &g_showHeartbeatWhitelistEditWindow)) {

        // ===== 规则名称 =====
        ImGuiGBK::Text("规则名称:");
        ImGui::SameLine(100);
        ImGui::SetNextItemWidth(300);
        ImGui::InputText("##rule_name", g_hbWhitelistNameBuffer, sizeof(g_hbWhitelistNameBuffer));

        ImGui::SameLine();
        ImGuiGBK::Checkbox("启用##rule_enable", &g_hbWhitelistEditData.isEnabled);

        ImGui::Spacing();
        ImGui::Separator();

        // ===== 搜索内容（WPE网格样式）=====
        ImGui::SeparatorText(ImGuiText::U("搜索内容（匹配的数据将跳过伪心跳）"));

        // 复用WPE的网格渲染函数
        ImGui::PushID("hb_whitelist_grid");

        // 固定列宽和间距
        const float cellWidth = 28.0f;
        const float cellSpacing = 2.0f;
        const float cellTotalWidth = cellWidth + cellSpacing;
        const int colsPerRow = 24;

        // 计算当前显示的起始位置
        int currentPos = g_hbWhitelistSearchScrollPos - WPE_GRID_CENTER;

        // 滚动控制区域
        ImGuiGBK::Text("位置:");
        ImGui::SameLine();
        ImGui::SetNextItemWidth(80);
        if (ImGui::InputInt("##scroll_pos", &currentPos, 0, 0, ImGuiInputTextFlags_EnterReturnsTrue)) {
            if (currentPos < WPE_GRID_MIN_POS) currentPos = WPE_GRID_MIN_POS;
            if (currentPos > WPE_GRID_MAX_POS - colsPerRow + 1) currentPos = WPE_GRID_MAX_POS - colsPerRow + 1;
            g_hbWhitelistSearchScrollPos = currentPos + WPE_GRID_CENTER;
        }

        ImGui::SameLine();
        if (ImGuiGBK::Button("<<##first")) {
            g_hbWhitelistSearchScrollPos = 0;
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button("<##prev")) {
            g_hbWhitelistSearchScrollPos -= colsPerRow;
            if (g_hbWhitelistSearchScrollPos < 0) g_hbWhitelistSearchScrollPos = 0;
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button(">##next")) {
            g_hbWhitelistSearchScrollPos += colsPerRow;
            if (g_hbWhitelistSearchScrollPos > WPE_GRID_TOTAL_SIZE - colsPerRow)
                g_hbWhitelistSearchScrollPos = WPE_GRID_TOTAL_SIZE - colsPerRow;
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button(">>##last")) {
            g_hbWhitelistSearchScrollPos = WPE_GRID_TOTAL_SIZE - colsPerRow;
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button("0##center")) {
            g_hbWhitelistSearchScrollPos = WPE_GRID_CENTER;
        }

        // 粘贴按钮
        ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.2f, 0.5f, 0.2f, 1.0f));
        if (ImGuiGBK::Button("粘贴##paste_wl")) {
            const char* clipboardText = ImGui::GetClipboardText();
            if (clipboardText && strlen(clipboardText) > 0) {
                std::vector<std::string> hexBytes = ParseHexStringFromClipboard(clipboardText);
                if (!hexBytes.empty()) {
                    int filled = FillGridFromHexBytes(g_hbWhitelistSearchGrid, g_hbWhitelistSearchScrollPos, hexBytes);
                    AB_LOG_INFO("[白名单] 粘贴成功，填充了 " + std::to_string(filled) + " 个字节");
                }
            }
        }
        ImGui::PopStyleColor();

        // 清空按钮
        ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.5f, 0.2f, 0.2f, 1.0f));
        if (ImGuiGBK::Button("清空##clear_wl")) {
            ClearHeartbeatWhitelistGrid();
        }
        ImGui::PopStyleColor();

        ImGui::SameLine();
        ImGuiGBK::TextColored(ImVec4(0.7f, 0.7f, 0.7f, 1.0f), "(留空=跳过, ??=通配符)");

        // 显示当前范围
        int displayStart = g_hbWhitelistSearchScrollPos - WPE_GRID_CENTER;
        int displayEnd = displayStart + colsPerRow - 1;
        ImGui::SameLine();
        ImGuiGBK::TextColored(ImVec4(0.5f, 0.8f, 0.5f, 1.0f), "[%d ~ %d]", displayStart, displayEnd);

        // 渲染位置编号行
        float startX = ImGui::GetCursorPosX();
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.4f, 0.7f, 1.0f, 1.0f));
        for (int col = 0; col < colsPerRow; col++) {
            int gridIdx = g_hbWhitelistSearchScrollPos + col;
            if (gridIdx >= WPE_GRID_TOTAL_SIZE) break;

            float posX = startX + col * cellTotalWidth;
            ImGui::SetCursorPosX(posX);

            int pos = gridIdx - WPE_GRID_CENTER;
            char posLabel[16];
            if (pos >= 0 && pos < 10) {
                snprintf(posLabel, sizeof(posLabel), "  %d ", pos);
            }
            else if (pos >= 10 && pos < 100) {
                snprintf(posLabel, sizeof(posLabel), " %d ", pos);
            }
            else if (pos >= 100) {
                snprintf(posLabel, sizeof(posLabel), "%d", pos);
            }
            else if (pos > -10) {
                snprintf(posLabel, sizeof(posLabel), " %d ", pos);
            }
            else {
                snprintf(posLabel, sizeof(posLabel), "%d", pos);
            }

            ImGui::SetNextItemWidth(cellWidth);
            ImGui::Text("%s", posLabel);

            if (col < colsPerRow - 1) {
                ImGui::SameLine(0, cellSpacing);
            }
        }
        ImGui::PopStyleColor();

        // 渲染十六进制输入框
        static int s_pendingFocusIdx_wl = -1;

        for (int col = 0; col < colsPerRow; col++) {
            int gridIdx = g_hbWhitelistSearchScrollPos + col;
            if (gridIdx >= WPE_GRID_TOTAL_SIZE) break;

            float posX = startX + col * cellTotalWidth;
            ImGui::SetCursorPosX(posX);

            ImGui::PushID(gridIdx);

            bool hasValue = g_hbWhitelistSearchGrid[gridIdx][0] != '\0';
            bool isWildcard = (g_hbWhitelistSearchGrid[gridIdx][0] == '?' && g_hbWhitelistSearchGrid[gridIdx][1] == '?');

            if (isWildcard) {
                ImGui::PushStyleColor(ImGuiCol_FrameBg, ImVec4(0.5f, 0.3f, 0.1f, 1.0f));
            }
            else if (hasValue) {
                ImGui::PushStyleColor(ImGuiCol_FrameBg, ImVec4(0.2f, 0.4f, 0.2f, 1.0f));
            }
            else {
                ImGui::PushStyleColor(ImGuiCol_FrameBg, ImVec4(0.15f, 0.15f, 0.15f, 1.0f));
            }

            if (s_pendingFocusIdx_wl == gridIdx) {
                ImGui::SetKeyboardFocusHere();
                s_pendingFocusIdx_wl = -1;
            }

            ImGui::SetNextItemWidth(cellWidth);
            if (ImGui::InputText("##hex", g_hbWhitelistSearchGrid[gridIdx], 3,
                ImGuiInputTextFlags_CharsUppercase | ImGuiInputTextFlags_AutoSelectAll)) {
                for (int i = 0; i < 2 && g_hbWhitelistSearchGrid[gridIdx][i]; i++) {
                    if (g_hbWhitelistSearchGrid[gridIdx][i] != '?') {
                        g_hbWhitelistSearchGrid[gridIdx][i] = toupper(g_hbWhitelistSearchGrid[gridIdx][i]);
                    }
                }

                if (strlen(g_hbWhitelistSearchGrid[gridIdx]) >= 2) {
                    int nextIdx = gridIdx + 1;
                    if (nextIdx < WPE_GRID_TOTAL_SIZE) {
                        s_pendingFocusIdx_wl = nextIdx;
                        if (nextIdx >= g_hbWhitelistSearchScrollPos + colsPerRow) {
                            g_hbWhitelistSearchScrollPos = nextIdx - colsPerRow + 1;
                        }
                    }
                }
            }

            ImGui::PopStyleColor();
            ImGui::PopID();

            if (col < colsPerRow - 1) {
                ImGui::SameLine(0, cellSpacing);
            }
        }

        ImGui::PopID();

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // ===== 匹配模式选择 =====
        ImGuiGBK::Text("匹配模式:");
        ImGui::SameLine(100);
        if (ImGui::RadioButton(ImGuiText::U("模式搜索（推荐）##hb_pattern_search"), g_hbWhitelistEditData.usePatternSearch)) {
            g_hbWhitelistEditData.usePatternSearch = true;
        }
        ImGui::SameLine();
        if (ImGui::RadioButton(ImGuiText::U("绝对位置匹配##hb_absolute_pos"), !g_hbWhitelistEditData.usePatternSearch)) {
            g_hbWhitelistEditData.usePatternSearch = false;
        }

        // 模式说明
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.6f, 0.6f, 0.6f, 1.0f));
        if (g_hbWhitelistEditData.usePatternSearch) {
            ImGuiGBK::Text("  模式搜索: 在整个数据包中搜索指定的字节序列，无论出现在什么位置都能匹配");
        }
        else {
            ImGuiGBK::Text("  绝对位置: 只检查数据包的固定位置是否等于指定值（位置必须精确）");
        }
        ImGui::PopStyleColor();

        ImGui::Spacing();

        // ===== 保存/取消按钮 =====
        if (ImGuiGBK::Button("保存##save_rule", ImVec2(120, 30))) {
            g_hbWhitelistEditData.name = g_hbWhitelistNameBuffer;
            g_hbWhitelistEditData.searchPattern = HeartbeatWhitelistGridToPattern(g_hbWhitelistSearchGrid);

            std::lock_guard<std::mutex> lock(g_heartbeatWhitelistMutex);

            if (g_heartbeatWhitelistIsNewRule) {
                g_hbWhitelistEditData.id = g_heartbeatWhitelistNextId++;
                g_heartbeatWhitelist.push_back(g_hbWhitelistEditData);
                AB_LOG_INFO("[白名单] 添加规则: " + g_hbWhitelistEditData.name);
            }
            else {
                for (auto& rule : g_heartbeatWhitelist) {
                    if (rule.id == g_hbWhitelistEditData.id) {
                        rule.name = g_hbWhitelistEditData.name;
                        rule.isEnabled = g_hbWhitelistEditData.isEnabled;
                        rule.searchPattern = g_hbWhitelistEditData.searchPattern;
                        rule.usePatternSearch = g_hbWhitelistEditData.usePatternSearch;
                        AB_LOG_INFO("[白名单] 更新规则: " + rule.name);
                        break;
                    }
                }
            }

            g_showHeartbeatWhitelistEditWindow = false;
            needsRedraw = true;
        }

        ImGui::SameLine();
        if (ImGuiGBK::Button("取消##cancel_rule", ImVec2(120, 30))) {
            g_showHeartbeatWhitelistEditWindow = false;
        }
    }
    ImGui::End();
}

