// ========== 采集白名单功能实现 ==========

// 清空采集白名单搜索网格
void ClearCollectorWhitelistGrid() {
    for (int i = 0; i < WPE_GRID_TOTAL_SIZE; i++) {
        g_collWhitelistSearchGrid[i][0] = '\0';
        g_collWhitelistSearchGrid[i][1] = '\0';
        g_collWhitelistSearchGrid[i][2] = '\0';
    }
    g_collWhitelistSearchScrollPos = WPE_GRID_CENTER;
}

// 将网格转换为搜索模式字符串
std::string CollectorWhitelistGridToPattern(char grid[][3]) {
    std::stringstream ss;
    bool first = true;
    for (int i = 0; i < WPE_GRID_TOTAL_SIZE; i++) {
        if (grid[i][0] != '\0') {
            int pos = i - WPE_GRID_CENTER;  // 转换为实际位置
            if (!first) ss << ",";
            ss << pos << "|" << grid[i];
            first = false;
        }
    }
    return ss.str();
}

// 将搜索模式字符串解析到网格
void CollectorWhitelistPatternToGrid(const std::string& pattern, char grid[][3], int& scrollPos) {
    // 先清空网格
    for (int i = 0; i < WPE_GRID_TOTAL_SIZE; i++) {
        grid[i][0] = '\0';
        grid[i][1] = '\0';
        grid[i][2] = '\0';
    }

    if (pattern.empty()) {
        scrollPos = WPE_GRID_CENTER;
        return;
    }

    std::stringstream ss(pattern);
    std::string part;
    int minPos = WPE_GRID_MAX_POS;

    while (std::getline(ss, part, ',')) {
        part.erase(std::remove(part.begin(), part.end(), ' '), part.end());
        if (part.empty()) continue;

        size_t pipePos = part.find('|');
        if (pipePos == std::string::npos) continue;

        try {
            int pos = std::stoi(part.substr(0, pipePos));
            std::string hexStr = part.substr(pipePos + 1);

            int gridIdx = pos + WPE_GRID_CENTER;
            if (gridIdx >= 0 && gridIdx < WPE_GRID_TOTAL_SIZE && hexStr.length() <= 2) {
                strncpy_s(grid[gridIdx], 3, hexStr.c_str(), 2);
                if (pos < minPos) minPos = pos;
            }
        }
        catch (...) {
            continue;
        }
    }

    // 设置滚动位置到第一个有值的位置
    if (minPos != WPE_GRID_MAX_POS) {
        scrollPos = minPos + WPE_GRID_CENTER;
        if (scrollPos < 0) scrollPos = 0;
    }
    else {
        scrollPos = WPE_GRID_CENTER;
    }
}

