// 检查数据是否匹配采集白名单规则
// 返回: true=命中白名单（允许写入内存池/数据库）, false=未命中
bool CheckCollectorWhitelist(const std::vector<uint8_t>& data, int& matchedIndex, std::string& matchedRuleName) {
    if (!g_collectorWhitelistEnabled) return false;

    std::lock_guard<std::mutex> lock(g_collectorWhitelistMutex);

    for (size_t ruleIdx = 0; ruleIdx < g_collectorWhitelist.size(); ruleIdx++) {
        CollectorWhitelistRule& rule = g_collectorWhitelist[ruleIdx];
        if (!rule.isEnabled || rule.searchPattern.empty()) continue;

        // 解析搜索模式，提取所有条件
        struct PatternItem {
            int relativePos;    // 相对位置（对于模式搜索）或绝对位置
            uint8_t value;      // 期望值
            bool isWildcard;    // 是否是完全通配符 (?? 或 **)
            bool isHighNibbleWildcard;  // 高4位是否通配 (*X 格式)
            bool isLowNibbleWildcard;   // 低4位是否通配 (X* 格式)
        };
        std::vector<PatternItem> patternItems;
        int minPos = INT_MAX;
        int maxPos = INT_MIN;

        std::stringstream ss(rule.searchPattern);
        std::string part;
        bool parseError = false;

        while (std::getline(ss, part, ',')) {
            part.erase(std::remove(part.begin(), part.end(), ' '), part.end());
            if (part.empty()) continue;

            size_t pipePos = part.find('|');
            if (pipePos == std::string::npos) continue;

            try {
                int pos = std::stoi(part.substr(0, pipePos));
                std::string hexStr = part.substr(pipePos + 1);

                // 转换为大写
                for (char& c : hexStr) {
                    c = std::toupper(c);
                }

                PatternItem item;
                item.relativePos = pos;
                item.isWildcard = (hexStr == "??" || hexStr == "**");
                item.isHighNibbleWildcard = false;
                item.isLowNibbleWildcard = false;
                item.value = 0;

                if (!item.isWildcard) {
                    if (hexStr.length() != 2) {
                        parseError = true;
                        break;
                    }

                    // ?? 新增：支持半字节通配符 (*X 或 X* 格式)
                    char highChar = hexStr[0];
                    char lowChar = hexStr[1];

                    // 解析高4位
                    if (highChar == '*') {
                        item.isHighNibbleWildcard = true;
                    } else {
                        int val = 0;
                        if (highChar >= '0' && highChar <= '9') val = highChar - '0';
                        else if (highChar >= 'A' && highChar <= 'F') val = 10 + (highChar - 'A');
                        else {
                            parseError = true;
                            break;
                        }
                        item.value = (val << 4);
                    }

                    // 解析低4位
                    if (lowChar == '*') {
                        item.isLowNibbleWildcard = true;
                    } else {
                        int val = 0;
                        if (lowChar >= '0' && lowChar <= '9') val = lowChar - '0';
                        else if (lowChar >= 'A' && lowChar <= 'F') val = 10 + (lowChar - 'A');
                        else {
                            parseError = true;
                            break;
                        }
                        item.value |= val;
                    }

                    // ?? 如果高低位都是通配符，等同于完全通配符
                    if (item.isHighNibbleWildcard && item.isLowNibbleWildcard) {
                        item.isWildcard = true;
                        item.isHighNibbleWildcard = false;
                        item.isLowNibbleWildcard = false;
                    }
                }

                if (parseError) break;

                patternItems.push_back(item);

                if (pos < minPos) minPos = pos;
                if (pos > maxPos) maxPos = pos;
            }
            catch (...) {
                parseError = true;
                break;
            }
        }

        if (parseError || patternItems.empty()) continue;

        bool matched = false;

        if (rule.usePatternSearch) {
            // ===== 模式搜索模式：在整个数据包中搜索模式 =====
            // 计算模式的实际长度（从最小位置到最大位置）
            int patternLength = maxPos - minPos + 1;

            // 遍历数据包的每个可能的起始位置
            for (int startPos = 0; startPos <= static_cast<int>(data.size()) - patternLength; startPos++) {
                bool allMatch = true;

                for (const auto& item : patternItems) {
                    // 计算在数据包中的实际位置
                    int actualPos = startPos + (item.relativePos - minPos);

                    // 检查位置是否有效
                    if (actualPos < 0 || actualPos >= static_cast<int>(data.size())) {
                        allMatch = false;
                        break;
                    }

                    // 通配符跳过比较
                    if (item.isWildcard) {
                        continue;
                    }

                    // ?? 新增：支持半字节通配符匹配
                    uint8_t dataByte = data[actualPos];

                    if (item.isHighNibbleWildcard) {
                        // 只检查低4位 (*X 格式)
                        if ((dataByte & 0x0F) != (item.value & 0x0F)) {
                            allMatch = false;
                            break;
                        }
                    } else if (item.isLowNibbleWildcard) {
                        // 只检查高4位 (X* 格式)
                        if ((dataByte & 0xF0) != (item.value & 0xF0)) {
                            allMatch = false;
                            break;
                        }
                    } else {
                        // 完全匹配
                        if (dataByte != item.value) {
                            allMatch = false;
                            break;
                        }
                    }
                }

                if (allMatch) {
                    matched = true;
                    break;
                }
            }
        }
        else {
            // ===== 绝对位置匹配模式（旧版兼容）=====
            bool allMatch = true;

            for (const auto& item : patternItems) {
                int pos = item.relativePos;

                // 检查位置是否有效
                if (pos < 0 || pos >= static_cast<int>(data.size())) {
                    allMatch = false;
                    break;
                }

                // 通配符跳过比较
                if (item.isWildcard) {
                    continue;
                }

                // ?? 新增：支持半字节通配符匹配
                uint8_t dataByte = data[pos];

                if (item.isHighNibbleWildcard) {
                    // 只检查低4位 (*X 格式)
                    if ((dataByte & 0x0F) != (item.value & 0x0F)) {
                        allMatch = false;
                        break;
                    }
                } else if (item.isLowNibbleWildcard) {
                    // 只检查高4位 (X* 格式)
                    if ((dataByte & 0xF0) != (item.value & 0xF0)) {
                        allMatch = false;
                        break;
                    }
                } else {
                    // 完全匹配
                    if (dataByte != item.value) {
                        allMatch = false;
                        break;
                    }
                }
            }

            matched = allMatch;
        }

        if (matched) {
            // 命中采集白名单
            rule.matchCount++;
            matchedIndex = static_cast<int>(ruleIdx);
            matchedRuleName = rule.name;
            AB_LOG_INFO_CAT(LOG_CAT_COLLECTOR, "[采集白名单] 命中规则: " + rule.name +
                " (命中次数: " + std::to_string(rule.matchCount) +
                ", 模式: " + (rule.usePatternSearch ? "搜索" : "绝对位置") + ")");
            return true;
        }
    }

    matchedIndex = -1;
    matchedRuleName = "";
    return false;
}

// 检查数据是否匹配采集黑名单规则
// 返回: true=命中黑名单（禁止写入内存池/数据库）, false=未命中
bool CheckCollectorBlacklist(const std::vector<uint8_t>& data, int& matchedIndex, std::string& matchedRuleName) {
    if (!g_collectorBlacklistEnabled) return false;

    std::lock_guard<std::mutex> lock(g_collectorBlacklistMutex);

    for (size_t ruleIdx = 0; ruleIdx < g_collectorBlacklist.size(); ruleIdx++) {
        CollectorBlacklistRule& rule = g_collectorBlacklist[ruleIdx];
        if (!rule.isEnabled || rule.searchPattern.empty()) continue;

        // 解析搜索模式（与白名单相同的逻辑）
        struct PatternItem {
            int relativePos;
            uint8_t value;
            bool isWildcard;    // 是否是完全通配符 (?? 或 **)
            bool isHighNibbleWildcard;  // 高4位是否通配 (*X 格式)
            bool isLowNibbleWildcard;   // 低4位是否通配 (X* 格式)
        };
        std::vector<PatternItem> patternItems;
        int minPos = INT_MAX;
        int maxPos = INT_MIN;

        std::stringstream ss(rule.searchPattern);
        std::string part;
        bool parseError = false;

        while (std::getline(ss, part, ',')) {
            part.erase(std::remove(part.begin(), part.end(), ' '), part.end());
            if (part.empty()) continue;

            size_t pipePos = part.find('|');
            if (pipePos == std::string::npos) continue;

            try {
                int pos = std::stoi(part.substr(0, pipePos));
                std::string hexStr = part.substr(pipePos + 1);

                for (char& c : hexStr) {
                    c = std::toupper(c);
                }

                PatternItem item;
                item.relativePos = pos;
                item.isWildcard = (hexStr == "??" || hexStr == "**");
                item.isHighNibbleWildcard = false;
                item.isLowNibbleWildcard = false;
                item.value = 0;

                if (!item.isWildcard) {
                    if (hexStr.length() != 2) {
                        parseError = true;
                        break;
                    }

                    // ?? 新增：支持半字节通配符 (*X 或 X* 格式)
                    char highChar = hexStr[0];
                    char lowChar = hexStr[1];

                    // 解析高4位
                    if (highChar == '*') {
                        item.isHighNibbleWildcard = true;
                    } else {
                        int val = 0;
                        if (highChar >= '0' && highChar <= '9') val = highChar - '0';
                        else if (highChar >= 'A' && highChar <= 'F') val = 10 + (highChar - 'A');
                        else {
                            parseError = true;
                            break;
                        }
                        item.value = (val << 4);
                    }

                    // 解析低4位
                    if (lowChar == '*') {
                        item.isLowNibbleWildcard = true;
                    } else {
                        int val = 0;
                        if (lowChar >= '0' && lowChar <= '9') val = lowChar - '0';
                        else if (lowChar >= 'A' && lowChar <= 'F') val = 10 + (lowChar - 'A');
                        else {
                            parseError = true;
                            break;
                        }
                        item.value |= val;
                    }

                    // ?? 如果高低位都是通配符，等同于完全通配符
                    if (item.isHighNibbleWildcard && item.isLowNibbleWildcard) {
                        item.isWildcard = true;
                        item.isHighNibbleWildcard = false;
                        item.isLowNibbleWildcard = false;
                    }
                }

                if (parseError) break;

                patternItems.push_back(item);

                if (pos < minPos) minPos = pos;
                if (pos > maxPos) maxPos = pos;
            }
            catch (...) {
                parseError = true;
                break;
            }
        }

        if (parseError || patternItems.empty()) continue;

        bool matched = false;

        if (rule.usePatternSearch) {
            // 模式搜索
            int patternLength = maxPos - minPos + 1;

            for (int startPos = 0; startPos <= static_cast<int>(data.size()) - patternLength; startPos++) {
                bool allMatch = true;

                for (const auto& item : patternItems) {
                    int actualPos = startPos + (item.relativePos - minPos);

                    if (actualPos < 0 || actualPos >= static_cast<int>(data.size())) {
                        allMatch = false;
                        break;
                    }

                    if (item.isWildcard) {
                        continue;
                    }

                    // ?? 新增：支持半字节通配符匹配
                    uint8_t dataByte = data[actualPos];

                    if (item.isHighNibbleWildcard) {
                        // 只检查低4位 (*X 格式)
                        if ((dataByte & 0x0F) != (item.value & 0x0F)) {
                            allMatch = false;
                            break;
                        }
                    } else if (item.isLowNibbleWildcard) {
                        // 只检查高4位 (X* 格式)
                        if ((dataByte & 0xF0) != (item.value & 0xF0)) {
                            allMatch = false;
                            break;
                        }
                    } else {
                        // 完全匹配
                        if (dataByte != item.value) {
                            allMatch = false;
                            break;
                        }
                    }
                }

                if (allMatch) {
                    matched = true;
                    break;
                }
            }
        }
        else {
            // 绝对位置匹配
            bool allMatch = true;

            for (const auto& item : patternItems) {
                int pos = item.relativePos;

                if (pos < 0 || pos >= static_cast<int>(data.size())) {
                    allMatch = false;
                    break;
                }

                if (item.isWildcard) {
                    continue;
                }

                // ?? 新增：支持半字节通配符匹配
                uint8_t dataByte = data[pos];

                if (item.isHighNibbleWildcard) {
                    // 只检查低4位 (*X 格式)
                    if ((dataByte & 0x0F) != (item.value & 0x0F)) {
                        allMatch = false;
                        break;
                    }
                } else if (item.isLowNibbleWildcard) {
                    // 只检查高4位 (X* 格式)
                    if ((dataByte & 0xF0) != (item.value & 0xF0)) {
                        allMatch = false;
                        break;
                    }
                } else {
                    // 完全匹配
                    if (dataByte != item.value) {
                        allMatch = false;
                        break;
                    }
                }
            }

            matched = allMatch;
        }

        if (matched) {
            // 命中采集黑名单
            rule.matchCount++;
            matchedIndex = static_cast<int>(ruleIdx);
            matchedRuleName = rule.name;
            AB_LOG_INFO_CAT(LOG_CAT_COLLECTOR, "[采集黑名单] 命中规则: " + rule.name +
                " (命中次数: " + std::to_string(rule.matchCount) +
                ", 模式: " + (rule.usePatternSearch ? "搜索" : "绝对位置") + ") - 禁止写入");
            return true;
        }
    }

    matchedIndex = -1;
    matchedRuleName = "";
    return false;
}

// 渲染采集白名单编辑窗口
void RenderCollectorWhitelistEditWindow(bool& needsRedraw) {
    if (!g_showCollectorWhitelistEditWindow) return;

    ImGui::SetNextWindowSize(ImVec2(750, 400), ImGuiCond_FirstUseEver);

    std::string windowTitle = g_collectorWhitelistIsNewRule ? "新建采集白名单规则##coll_whitelist_edit" : "编辑采集白名单规则##coll_whitelist_edit";
    if (ImGui::Begin(ImGuiText::U(windowTitle.c_str()), &g_showCollectorWhitelistEditWindow)) {

        // ===== 规则名称 =====
        ImGuiGBK::Text("规则名称:");
        ImGui::SameLine(100);
        ImGui::SetNextItemWidth(300);
        ImGui::InputText("##coll_rule_name", g_collWhitelistNameBuffer, sizeof(g_collWhitelistNameBuffer));

        ImGui::SameLine();
        ImGuiGBK::Checkbox("启用##coll_rule_enable", &g_collWhitelistEditData.isEnabled);

        ImGui::Spacing();
        ImGui::Separator();

        // ===== 搜索内容（WPE网格样式）=====
        ImGui::SeparatorText(ImGuiText::U("搜索内容（匹配的数据将不写入内存池）"));

        // 复用WPE的网格渲染函数
        ImGui::PushID("coll_whitelist_grid");

        // 固定列宽和间距
        const float cellWidth = 28.0f;
        const float cellSpacing = 2.0f;
        int colsPerRow = 24;

        // 位置导航
        int currentPos = g_collWhitelistSearchScrollPos - WPE_GRID_CENTER;
        ImGuiGBK::Text("当前位置: %d", currentPos);
        ImGui::SameLine();
        ImGui::SetNextItemWidth(80);
        if (ImGui::InputInt("##goto_pos", &currentPos, 0, 0)) {
            g_collWhitelistSearchScrollPos = currentPos + WPE_GRID_CENTER;
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button("首##first_coll")) {
            g_collWhitelistSearchScrollPos = 0;
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button("上##prev_coll")) {
            g_collWhitelistSearchScrollPos -= colsPerRow;
            if (g_collWhitelistSearchScrollPos < 0) g_collWhitelistSearchScrollPos = 0;
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button("下##next_coll")) {
            g_collWhitelistSearchScrollPos += colsPerRow;
            if (g_collWhitelistSearchScrollPos > WPE_GRID_TOTAL_SIZE - colsPerRow)
                g_collWhitelistSearchScrollPos = WPE_GRID_TOTAL_SIZE - colsPerRow;
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button("尾##last_coll")) {
            g_collWhitelistSearchScrollPos = WPE_GRID_TOTAL_SIZE - colsPerRow;
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button("零点##zero_coll")) {
            g_collWhitelistSearchScrollPos = WPE_GRID_CENTER;
        }

        ImGui::SameLine();
        if (ImGuiGBK::Button("粘贴##paste_coll")) {
            if (ImGui::GetClipboardText()) {
                std::string clipboardText = ImGui::GetClipboardText();
                std::vector<std::string> hexBytes = ParseHexStringFromClipboard(clipboardText);
                if (!hexBytes.empty()) {
                    int filled = FillGridFromHexBytes(g_collWhitelistSearchGrid, g_collWhitelistSearchScrollPos, hexBytes);
                    AB_LOG_INFO("[采集白名单] 粘贴成功，填充了 " + std::to_string(filled) + " 个字节");
                }
            }
        }
        ImGui::SameLine();
        if (ImGuiGBK::Button("清空##clear_coll")) {
            ClearCollectorWhitelistGrid();
        }

        ImGui::Spacing();

        // 位置标签
        int displayStart = g_collWhitelistSearchScrollPos - WPE_GRID_CENTER;

        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.5f, 0.5f, 0.5f, 1.0f));
        for (int col = 0; col < colsPerRow; col++) {
            ImGui::PushID(col * 1000 + 1);
            int gridIdx = g_collWhitelistSearchScrollPos + col;
            int actualPos = gridIdx - WPE_GRID_CENTER;

            char posLabel[8];
            if (actualPos >= 0) {
                sprintf_s(posLabel, "+%d", actualPos);
            }
            else {
                sprintf_s(posLabel, "%d", actualPos);
            }

            ImGui::SetNextItemWidth(cellWidth);
            ImGui::Text("%s", posLabel);
            ImGui::PopID();

            if (col < colsPerRow - 1) {
                ImGui::SameLine(0, cellSpacing);
            }
        }
        ImGui::PopStyleColor();

        // 十六进制输入格子
        for (int col = 0; col < colsPerRow; col++) {
            int gridIdx = g_collWhitelistSearchScrollPos + col;
            if (gridIdx < 0 || gridIdx >= WPE_GRID_TOTAL_SIZE) continue;

            ImGui::PushID(gridIdx);

            bool hasValue = g_collWhitelistSearchGrid[gridIdx][0] != '\0';
            bool isWildcard = (g_collWhitelistSearchGrid[gridIdx][0] == '?' && g_collWhitelistSearchGrid[gridIdx][1] == '?');

            if (hasValue) {
                if (isWildcard) {
                    ImGui::PushStyleColor(ImGuiCol_FrameBg, ImVec4(0.3f, 0.3f, 0.5f, 1.0f));
                }
                else {
                    ImGui::PushStyleColor(ImGuiCol_FrameBg, ImVec4(0.0f, 0.3f, 0.0f, 1.0f));
                }
            }

            ImGui::SetNextItemWidth(cellWidth);
            if (ImGui::InputText("##hex_coll", g_collWhitelistSearchGrid[gridIdx], 3,
                ImGuiInputTextFlags_CharsUppercase | ImGuiInputTextFlags_AutoSelectAll)) {
                for (int i = 0; i < 2 && g_collWhitelistSearchGrid[gridIdx][i]; i++) {
                    if (g_collWhitelistSearchGrid[gridIdx][i] != '?') {
                        g_collWhitelistSearchGrid[gridIdx][i] = toupper(g_collWhitelistSearchGrid[gridIdx][i]);
                    }
                }
                // 自动跳转到下一格
                if (strlen(g_collWhitelistSearchGrid[gridIdx]) >= 2) {
                    int nextIdx = gridIdx + 1;
                    if (nextIdx < WPE_GRID_TOTAL_SIZE) {
                        ImGui::SetKeyboardFocusHere(0);
                        if (nextIdx >= g_collWhitelistSearchScrollPos + colsPerRow) {
                            g_collWhitelistSearchScrollPos = nextIdx - colsPerRow + 1;
                        }
                    }
                }
            }

            if (hasValue) {
                ImGui::PopStyleColor();
            }

            ImGui::PopID();

            if (col < colsPerRow - 1) {
                ImGui::SameLine(0, cellSpacing);
            }
        }

        ImGui::PopID();

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // ===== 匹配模式选择 =====
        ImGuiGBK::Text("匹配模式:");
        ImGui::SameLine(100);
        if (ImGui::RadioButton(ImGuiText::U("模式搜索（推荐）##pattern_search"), g_collWhitelistEditData.usePatternSearch)) {
            g_collWhitelistEditData.usePatternSearch = true;
        }
        ImGui::SameLine();
        if (ImGui::RadioButton(ImGuiText::U("绝对位置匹配##absolute_pos"), !g_collWhitelistEditData.usePatternSearch)) {
            g_collWhitelistEditData.usePatternSearch = false;
        }

        // 模式说明
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.6f, 0.6f, 0.6f, 1.0f));
        if (g_collWhitelistEditData.usePatternSearch) {
            ImGuiGBK::Text("  模式搜索: 在整个数据包中搜索指定的字节序列，无论出现在什么位置都能匹配");
        }
        else {
            ImGuiGBK::Text("  绝对位置: 只检查数据包的固定位置是否等于指定值（位置必须精确）");
        }
        ImGui::PopStyleColor();

        ImGui::Spacing();

        // ===== 保存/取消按钮 =====
        if (ImGuiGBK::Button("保存##save_coll_rule", ImVec2(120, 30))) {
            g_collWhitelistEditData.name = g_collWhitelistNameBuffer;
            g_collWhitelistEditData.searchPattern = CollectorWhitelistGridToPattern(g_collWhitelistSearchGrid);

            std::lock_guard<std::mutex> lock(g_collectorWhitelistMutex);

            if (g_collectorWhitelistIsNewRule) {
                g_collWhitelistEditData.id = g_collectorWhitelistNextId++;
                g_collectorWhitelist.push_back(g_collWhitelistEditData);
                AB_LOG_INFO("[采集白名单] 添加规则: " + g_collWhitelistEditData.name);
            }
            else {
                for (auto& rule : g_collectorWhitelist) {
                    if (rule.id == g_collWhitelistEditData.id) {
                        rule.name = g_collWhitelistEditData.name;
                        rule.isEnabled = g_collWhitelistEditData.isEnabled;
                        rule.searchPattern = g_collWhitelistEditData.searchPattern;
                        rule.usePatternSearch = g_collWhitelistEditData.usePatternSearch;
                        AB_LOG_INFO("[采集白名单] 更新规则: " + rule.name);
                        break;
                    }
                }
            }

            g_showCollectorWhitelistEditWindow = false;
            needsRedraw = true;
        }

        ImGui::SameLine();
        if (ImGuiGBK::Button("取消##cancel_coll_rule", ImVec2(120, 30))) {
            g_showCollectorWhitelistEditWindow = false;
        }
    }
    ImGui::End();
}

