            ofn.nMaxFile = sizeof(filepath);
            ofn.lpstrFilter = "Binary Files (*.bin)\0*.bin\0All Files (*.*)\0*.*\0";
            ofn.lpstrDefExt = "bin";
            ofn.Flags = OFN_PATHMUSTEXIST | OFN_OVERWRITEPROMPT;

            std::string defaultName = "hb_original_" + std::to_string(localCopy.id) + ".bin";
            strcpy_s(filepath, defaultName.c_str());

            if (GetSaveFileNameA(&ofn)) {
                std::ofstream file(filepath, std::ios::binary);
                if (file.is_open()) {
                    file.write(reinterpret_cast<const char*>(localCopy.originalRawData.data()),
                        localCopy.originalRawData.size());
                    file.close();
                    MessageBoxA(g_mainHwnd, "原始数据导出成功！", "提示", MB_OK | MB_ICONINFORMATION);
                }
            }
