                ImDrawList* btnDrawList = ImGui::GetWindowDrawList();
                float radius = buttonHeight * 0.2f;
                int segments = 16;
                for (int i = 0; i < segments; i++) {
                    float angle = g_loginState.loadingAngle + (i * 2.0f * 3.14159f / segments);
                    float alpha = 1.0f - (i / (float)segments);
                    ImVec2 pos = ImVec2(
                        buttonCenter.x + cosf(angle) * radius,
                        buttonCenter.y + sinf(angle) * radius
                    );
                    btnDrawList->AddCircleFilled(pos, 2.5f, IM_COL32(255, 255, 255, (int)(alpha * 255)));
                }
