                                CloudIntegration::CloudConfig cfg;
                                cfg.serverIp = k_cloudServerIp;
                                cfg.serverPort = k_cloudServerPort;
                                cfg.softwareName = k_cloudSoftwareName;
                                cfg.timeoutMs = g_cloudNetTimeoutMs.load();
