// ========== 检查是否允许解绑 ==========
void CheckUnbindAllowed() {
    try {
        AB_LOG_INFO_CAT(LOG_CAT_LOGIN_AUTH, "[解绑检查] 开始检查解绑权限...");

        g_loginState.checkingUnbind = true;

        // 获取设备码
        std::string deviceCode = GetDeviceCode();

        // 准备请求数据
        Json::Value requestJson;
        requestJson["client_version"] = "3.0";
        requestJson["client_time"] = (Json::Int64)time(NULL);
        requestJson["device_code"] = deviceCode;

        std::string host(API_SERVER_HOST.begin(), API_SERVER_HOST.end());
        std::string path(API_CHECK_UNBIND_PATH.begin(), API_CHECK_UNBIND_PATH.end());

        std::string response = HttpJsonRequestWithSocket(
            host,
            API_SERVER_PORT,
            path,
            requestJson,
            true
        );

        g_loginState.checkingUnbind = false;

        if (response.empty()) {
            AB_LOG_WARNING("[解绑检查] 请求失败，默认允许解绑");
            g_loginState.allowUnbind = true;  // 请求失败时默认允许
            return;
        }

        // 解析响应
        Json::CharReaderBuilder readerBuilder;
        Json::Value responseJson;
        std::string errs;
        std::istringstream iss(response);

        if (!Json::parseFromStream(readerBuilder, iss, &responseJson, &errs)) {
            AB_LOG_WARNING("[解绑检查] JSON解析失败: " + errs);
            g_loginState.allowUnbind = true;  // 解析失败时默认允许
            return;
        }

        int code = responseJson["code"].asInt();
        if (code == 200 && responseJson.isMember("data")) {
            Json::Value data = responseJson["data"];
            g_loginState.allowUnbind = data.isMember("allow_unbind") && data["allow_unbind"].asBool();
            AB_LOG_INFO_CAT(LOG_CAT_LOGIN_AUTH, "[解绑检查] 允许解绑: " + std::string(g_loginState.allowUnbind ? "是" : "否"));
        }
        else {
            g_loginState.allowUnbind = true;  // 服务器返回错误时默认允许
            AB_LOG_WARNING("[解绑检查] 服务器返回错误码: " + std::to_string(code) + "，默认允许解绑");
        }
    }
    catch (const std::exception& ex) {
        AB_LOG_ERROR("[解绑检查] 异常: " + std::string(ex.what()));
        g_loginState.allowUnbind = true;  // 异常时默认允许
        g_loginState.checkingUnbind = false;
    }
}

