// ========== 执行解绑机器码 ==========
bool PerformUnbind() {
    try {
        AB_LOG_INFO_CAT(LOG_CAT_LOGIN_AUTH, "[解绑] ========== 开始解绑流程 ==========");

        // 获取设备码
        std::string deviceCode = GetDeviceCode();

        if (deviceCode.empty()) {
            g_loginState.unbindMessage = "无法获取设备码";
            AB_LOG_ERROR("[解绑] 设备码获取失败");
            return false;
        }

        AB_LOG_INFO_CAT(LOG_CAT_LOGIN_AUTH, "[解绑] 设备码预览: " + deviceCode.substr(0, 16) + "...");

        // 准备请求数据
        Json::Value requestJson;
        requestJson["client_version"] = "3.0";
        requestJson["client_time"] = (Json::Int64)time(NULL);
        requestJson["device_code"] = deviceCode;

        std::string host(API_SERVER_HOST.begin(), API_SERVER_HOST.end());
        std::string path(API_UNBIND_PATH.begin(), API_UNBIND_PATH.end());

        AB_LOG_INFO_CAT(LOG_CAT_LOGIN_AUTH, "[解绑] 发送解绑请求...");

        std::string response = HttpJsonRequestWithSocket(
            host,
            API_SERVER_PORT,
            path,
            requestJson,
            true
        );

        if (response.empty()) {
            g_loginState.unbindMessage = "网络请求失败，请检查网络连接";
            AB_LOG_ERROR("[解绑] 网络请求返回空响应");
            return false;
        }

        AB_LOG_INFO_CAT(LOG_CAT_LOGIN_AUTH, "[解绑] 收到响应，长度: " + std::to_string(response.length()));

        // 解析JSON响应
        Json::CharReaderBuilder readerBuilder;
        Json::Value responseJson;
        std::string errs;
        std::istringstream iss(response);

        if (!Json::parseFromStream(readerBuilder, iss, &responseJson, &errs)) {
            g_loginState.unbindMessage = "服务器响应格式错误";
            AB_LOG_ERROR("[解绑] JSON解析失败: " + errs);
            return false;
        }

        int code = responseJson["code"].asInt();
        std::string msgUtf8 = responseJson["msg"].asString();
        std::string msg = ImGuiText::UTF8ToGBK(msgUtf8);

        AB_LOG_INFO_CAT(LOG_CAT_LOGIN_AUTH, "[解绑] 服务器返回码: " + std::to_string(code));
        AB_LOG_INFO_CAT(LOG_CAT_LOGIN_AUTH, "[解绑] 服务器消息: " + msg);

        g_loginState.unbindMessage = msg;

        if (code == 200) {
            AB_LOG_INFO_CAT(LOG_CAT_LOGIN_AUTH, "[解绑] 解绑成功！");
            return true;
        }
        else {
            AB_LOG_WARNING("[解绑] 解绑失败: " + msg);
            return false;
        }
    }
    catch (const std::exception& ex) {
        AB_LOG_ERROR("[解绑] 异常: " + std::string(ex.what()));
        g_loginState.unbindMessage = "发生异常，请重试";
        return false;
    }
}

