// ===== 预登录版本门禁检查函数 =====
#pragma optimize("", off)
static bool __declspec(noinline) DecideLoginAllowedByUpdateGateLocal(
    const CloudIntegration::CloudUpdateInfo& snap,
    const std::string& updateErr,
    bool fetchStarted,
    std::string& outMessage) {
    AB_SP_BEGIN_ULTRA("WM.Login.UpdateGate");

    outMessage.clear();
    bool allow = true;

    // 版本检查失败：禁止登录（fail-closed），避免通过"阻断版本检查"绕过最低版本门禁
    if (!updateErr.empty()) {
        outMessage = (updateErr.rfind("版本检查", 0) == 0) ? updateErr : ("版本检查失败: " + updateErr);
        allow = false;
    }
    // 版本检查尚未完成（未启动/进行中）：禁止登录，避免"先登录后才发现低版本"的窗口期
    else if (!snap.valid) {
        outMessage = fetchStarted ? "版本检查中，请稍后再登录" : "版本检查未完成，请稍后再登录";
        allow = false;
    }
    else {
        // 最低版本门禁：禁止低版本登录
        if (snap.minVerEnabled && snap.minVer > 0 && snap.localVer > 0 && snap.localVer < snap.minVer) {
            outMessage =
                "当前版本过低（本地:" + std::to_string(snap.localVer) +
                " 最低:" + std::to_string(snap.minVer) +
                "），请更新后再登录";
            allow = false;
        }
        // 强制更新：若发现新版本且标记强制更新，则禁止登录
        else if (snap.forceUpdate && snap.serverVer > snap.localVer) {
            outMessage =
                "发现强制更新版本（本地:" + std::to_string(snap.localVer) +
                " 最新:" + std::to_string(snap.serverVer) +
                "），请更新后再登录";
            allow = false;
        }
    }

    AB_SP_END();
    return allow;
}

